//! Headless `ptt pack` and `ptt mcp` CLI — same core engine as the desktop app.

use std::collections::HashSet;
use std::env;
use std::fs;
use std::io::{self, BufWriter, Write};
use std::path::{Path, PathBuf};
use std::process;

use globset::{Glob, GlobSet, GlobSetBuilder};
use ptt::core::budget::{fit_workspace_to_bpe_budget, prefit_by_estimate_with_graph};
use ptt::core::deps::DependencyGraph;
use ptt::core::git::{compute_git_diff, inspect_git_context, GitRepoContext};
use ptt::core::output::{
    write_output_with_stats, OutputFormat, PreparedWorkspace, WriteOptions, DEFAULT_MAX_FILE_SIZE,
};
use ptt::core::tokenizer::TokenizerModel;
use ptt::core::walker::{
    is_default_excluded_path, is_junk_dir_name, normalize_rel_path, walk, DirEntryMeta,
};

const USAGE: &str = "\
ptt pack — pack a folder into LLM-ready text (headless)
ptt mcp  — run Model Context Protocol (MCP) JSON-RPC 2.0 server over stdio

USAGE:
  ptt pack [DIR] [OPTIONS]
  ptt mcp [DIR]

ARGS:
  [DIR]                   Project root (default: current directory)

OPTIONS:
  -f, --format <FMT>      xml | markdown | json | plain  (default: xml)
  -o, --output <FILE>     Write to file instead of stdout
  -c, --copy              Copy packed output directly to system clipboard
      --preset <PRESET>   source | docs | all
      --pin <PATH>        Pin a project file so --max-tokens fitting never drops it (repeatable)
      --include <GLOB>    Include only files matching glob (repeatable)
      --exclude <GLOB>    Exclude files matching glob (repeatable)
      --skeleton [GLOB]   Pack all files (or files matching GLOB) as AST skeletons
      --git-modified      Select only Git modified / staged / untracked files
      --git-branch        Select only files changed on current branch vs base branch
      --git-diff          Include unified <git_diff> in packed output
      --max-tokens <N>    Fit the pack within N tokens (strict final-artifact limit)
      --tokenizer <MODEL> o200k_base | cl100k_base | claude | gemini (default: o200k_base)
      --no-redact         Disable automatic secret redaction
      --no-summary        Omit XML file summary (directory listing remains)
      --max-size <N>      Per-file size limit in bytes (default: 2097152)
      --prompt <TEXT>     Append <task_instructions> prompt at the end of the pack
  -h, --help              Show this help

EXAMPLES:
  ptt pack .
  ptt pack ./my-app -f markdown -o context.md
  ptt pack . --preset source --skeleton --max-tokens 128000 -c
  ptt pack . --git-modified --git-diff
  ptt mcp .
";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CliPreset {
    Source,
    Docs,
    All,
}

#[derive(Debug)]
pub struct PackArgs {
    pub dir: PathBuf,
    pub format: OutputFormat,
    pub output: Option<PathBuf>,
    pub copy_to_clipboard: bool,
    pub include_summary: bool,
    pub max_file_size: u64,
    pub preset: Option<CliPreset>,
    pub pinned_paths: Vec<String>,
    pub include_globs: Vec<String>,
    pub exclude_globs: Vec<String>,
    pub skeleton: bool,
    pub skeleton_globs: Vec<String>,
    pub git_modified: bool,
    pub git_branch: bool,
    pub git_diff: bool,
    pub max_tokens: Option<usize>,
    pub tokenizer_model: TokenizerModel,
    pub redact_secrets: bool,
    pub task_prompt: Option<String>,
}

impl Default for PackArgs {
    fn default() -> Self {
        Self {
            dir: PathBuf::from("."),
            format: OutputFormat::Xml,
            output: None,
            copy_to_clipboard: false,
            include_summary: true,
            max_file_size: DEFAULT_MAX_FILE_SIZE,
            preset: None,
            pinned_paths: Vec::new(),
            include_globs: Vec::new(),
            exclude_globs: Vec::new(),
            skeleton: false,
            skeleton_globs: Vec::new(),
            git_modified: false,
            git_branch: false,
            git_diff: false,
            max_tokens: None,
            tokenizer_model: TokenizerModel::O200kBase,
            redact_secrets: true,
            task_prompt: None,
        }
    }
}

pub enum Launch {
    Headless,
    Desktop(Option<String>),
}

fn desktop_folder(argv: &[String]) -> Result<Option<String>, String> {
    if argv.is_empty() {
        return Ok(None);
    }
    if argv.len() != 1 || argv[0].starts_with('-') {
        return Err("Use ptt [DIR] for desktop or ptt pack [DIR] [OPTIONS]".into());
    }
    let path = PathBuf::from(&argv[0]);
    if !path.is_dir() {
        return Err(format!("Unknown command or invalid directory: {}", argv[0]));
    }
    Ok(Some(
        path.canonicalize()
            .map_err(|error| error.to_string())?
            .to_string_lossy()
            .into_owned(),
    ))
}

pub fn maybe_run() -> Launch {
    let mut argv = env::args().skip(1).collect::<Vec<_>>();
    if argv.is_empty() {
        return Launch::Desktop(None);
    }
    let cmd = argv[0].as_str();
    if cmd == "mcp" || cmd == "--mcp" {
        argv.remove(0);
        let dir = argv
            .first()
            .filter(|s| !s.starts_with('-'))
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from("."));
        if argv.iter().any(|a| a == "-h" || a == "--help") {
            print!("{USAGE}");
            process::exit(0);
        }
        if let Err(e) = crate::mcp::run_mcp_stdio(dir) {
            eprintln!("ptt mcp: {e}");
            process::exit(1);
        }
        return Launch::Headless;
    }

    if cmd != "pack" && cmd != "--pack" {
        if matches!(cmd, "-h" | "--help") {
            print_top_help();
            process::exit(0);
        }
        if matches!(cmd, "-V" | "--version") {
            println!("ptt {}", env!("CARGO_PKG_VERSION"));
            process::exit(0);
        }
        return match desktop_folder(&argv) {
            Ok(folder) => Launch::Desktop(folder),
            Err(error) => {
                eprintln!("ptt: {error}");
                process::exit(2);
            }
        };
    }
    argv.remove(0);
    match parse_args(&argv) {
        Ok(args) => {
            if let Err(e) = run_pack(&args) {
                eprintln!("ptt pack: {e}");
                process::exit(1);
            }
            Launch::Headless
        }
        Err(e) => {
            eprintln!("ptt pack: {e}\n\n{USAGE}");
            process::exit(2);
        }
    }
}

fn print_top_help() {
    println!(
        "ptt {} — ProjectToText\n\n\
         Desktop:  ptt [DIR] (or launch the app bundle)\n\
         Headless: ptt pack [DIR] [OPTIONS]\n\
         MCP:      ptt mcp [DIR]\n\n\
         {USAGE}",
        env!("CARGO_PKG_VERSION")
    );
}

pub fn parse_args(argv: &[String]) -> Result<PackArgs, String> {
    let mut args = PackArgs::default();
    let mut positional_dir = false;

    let mut i = 0;
    while i < argv.len() {
        let a = argv[i].as_str();
        match a {
            "-h" | "--help" => {
                print!("{USAGE}");
                process::exit(0);
            }
            "-f" | "--format" => {
                i += 1;
                let v = argv.get(i).ok_or("missing value for --format")?;
                args.format = parse_format(v)?;
            }
            "-o" | "--output" => {
                i += 1;
                let v = argv.get(i).ok_or("missing value for --output")?;
                args.output = Some(PathBuf::from(v));
            }
            "-c" | "--copy" => {
                args.copy_to_clipboard = true;
            }
            "--preset" => {
                i += 1;
                let v = argv.get(i).ok_or("missing value for --preset")?;
                args.preset = Some(parse_preset(v)?);
            }
            "--pin" => {
                i += 1;
                let v = argv.get(i).ok_or("missing value for --pin")?;
                args.pinned_paths.push(v.clone());
            }
            "--include" => {
                i += 1;
                let v = argv.get(i).ok_or("missing value for --include")?;
                args.include_globs.push(v.clone());
            }
            "--exclude" => {
                i += 1;
                let v = argv.get(i).ok_or("missing value for --exclude")?;
                args.exclude_globs.push(v.clone());
            }
            "--skeleton" | "--skeleton-all" => {
                // Support both `--skeleton` (all files) and `--skeleton <GLOB>` (when next token is a glob pattern)
                if a == "--skeleton" {
                    if let Some(next) = argv.get(i + 1) {
                        if !next.starts_with('-')
                            && (next.contains('*') || next.contains('?') || next.contains('['))
                        {
                            i += 1;
                            args.skeleton_globs.push(next.clone());
                        } else {
                            args.skeleton = true;
                        }
                    } else {
                        args.skeleton = true;
                    }
                } else {
                    args.skeleton = true;
                }
            }
            "--git-modified" => {
                args.git_modified = true;
            }
            "--git-branch" => {
                args.git_branch = true;
            }
            "--git-diff" => {
                args.git_diff = true;
            }
            "--max-tokens" => {
                i += 1;
                let v = argv.get(i).ok_or("missing value for --max-tokens")?;
                let parsed = v
                    .parse::<usize>()
                    .map_err(|_| format!("invalid --max-tokens: {v}"))?;
                if parsed == 0 {
                    return Err("--max-tokens must be greater than 0".into());
                }
                args.max_tokens = Some(parsed);
            }
            "--tokenizer" | "--model" => {
                i += 1;
                let v = argv.get(i).ok_or("missing value for --tokenizer")?;
                args.tokenizer_model = TokenizerModel::try_parse(v)?;
            }
            "--no-redact" => {
                args.redact_secrets = false;
            }
            "--no-summary" => args.include_summary = false,
            "--max-size" => {
                i += 1;
                let v = argv.get(i).ok_or("missing value for --max-size")?;
                args.max_file_size = v
                    .parse::<u64>()
                    .map_err(|_| format!("invalid --max-size: {v}"))?;
            }
            "--prompt" | "--task" => {
                i += 1;
                let v = argv.get(i).ok_or("missing value for --prompt")?;
                args.task_prompt = Some(v.clone());
            }
            s if s.starts_with('-') => return Err(format!("unknown option: {s}")),
            s => {
                if positional_dir {
                    return Err(format!("unexpected argument: {s}"));
                }
                args.dir = PathBuf::from(s);
                positional_dir = true;
            }
        }
        i += 1;
    }

    Ok(args)
}

fn parse_format(s: &str) -> Result<OutputFormat, String> {
    match s.to_ascii_lowercase().as_str() {
        "xml" => Ok(OutputFormat::Xml),
        "markdown" | "md" => Ok(OutputFormat::Markdown),
        "json" => Ok(OutputFormat::Json),
        "plain" | "txt" | "text" => Ok(OutputFormat::Plain),
        other => Err(format!(
            "unknown format '{other}' (use xml|markdown|json|plain)"
        )),
    }
}

pub(crate) fn parse_preset(s: &str) -> Result<CliPreset, String> {
    match s.to_ascii_lowercase().as_str() {
        "source" | "src" => Ok(CliPreset::Source),
        "docs" | "doc" => Ok(CliPreset::Docs),
        "all" | "clean" => Ok(CliPreset::All),
        other => Err(format!("unknown preset '{other}' (use source|docs|all)")),
    }
}

const SOURCE_EXTS: &[&str] = &[
    ".ts",
    ".tsx",
    ".js",
    ".jsx",
    ".mjs",
    ".cjs",
    ".vue",
    ".svelte",
    ".rs",
    ".go",
    ".py",
    ".java",
    ".cpp",
    ".c",
    ".h",
    ".hpp",
    ".cs",
    ".fs",
    ".fsx",
    ".fsi",
    ".vb",
    ".xaml",
    ".axaml",
    ".razor",
    ".cshtml",
    ".csproj",
    ".fsproj",
    ".vbproj",
    ".sln",
    ".props",
    ".targets",
    ".resx",
    ".editorconfig",
    ".md",
    ".txt",
    ".json",
    ".jsonc",
    ".toml",
    ".yaml",
    ".yml",
    ".xml",
    ".css",
    ".scss",
    ".html",
    ".sql",
    ".sh",
    ".ps1",
    ".rb",
    ".kt",
    ".swift",
];

const DOC_EXTS: &[&str] = &[".md", ".txt", ".rst", ".adoc"];

fn is_source_path(path: &str) -> bool {
    let lower = path.to_ascii_lowercase();
    if SOURCE_EXTS.iter().any(|ext| lower.ends_with(ext)) {
        return true;
    }
    lower.ends_with(".xaml.cs") || lower.ends_with(".razor.cs") || lower.ends_with(".designer.cs")
}

fn is_junk_rel_path(path: &str) -> bool {
    path.split('/').any(is_junk_dir_name)
}

fn matches_preset(path: &str, preset: CliPreset) -> bool {
    if is_junk_rel_path(path) || is_default_excluded_path(path) {
        return false;
    }
    let lower = path.to_ascii_lowercase();
    match preset {
        CliPreset::All => true,
        CliPreset::Docs => is_source_path(path) || DOC_EXTS.iter().any(|ext| lower.ends_with(ext)),
        CliPreset::Source => is_source_path(path),
    }
}

fn build_globset(patterns: &[String]) -> Result<Option<GlobSet>, String> {
    if patterns.is_empty() {
        return Ok(None);
    }
    let mut builder = GlobSetBuilder::new();
    for pat in patterns {
        let glob = Glob::new(pat).map_err(|e| format!("invalid glob '{pat}': {e}"))?;
        builder.add(glob);
    }
    builder
        .build()
        .map(Some)
        .map_err(|e| format!("failed to build globset: {e}"))
}

impl PackArgs {
    /// The `--pin` paths in the normalized form the budget fitter compares against.
    pub(crate) fn pinned_rel_paths(&self) -> HashSet<String> {
        self.pinned_paths
            .iter()
            .map(|p| normalize_rel_path(Path::new(p)))
            .collect()
    }
}

/// Filters and auto-fits `entries` according to `args`, reusing precomputed git context and dependency graph if provided.
pub fn filter_entries_for_cli_with_context(
    entries: Vec<DirEntryMeta>,
    root: &Path,
    args: &PackArgs,
    git_ctx: Option<&GitRepoContext>,
    dep_graph: Option<&DependencyGraph>,
) -> Result<(Vec<DirEntryMeta>, HashSet<String>), String> {
    let include_set = build_globset(&args.include_globs)?;
    let exclude_set = build_globset(&args.exclude_globs)?;
    let skeleton_glob_set = build_globset(&args.skeleton_globs)?;

    let git_mod_set: Option<HashSet<String>> = if args.git_modified || args.git_branch {
        let mut set = HashSet::new();
        if let Some(ctx) = git_ctx {
            if args.git_modified {
                set.extend(ctx.modified_files.clone());
            }
            if args.git_branch {
                set.extend(ctx.branch_changed_files.clone());
            }
        } else {
            let ctx = inspect_git_context(root);
            if args.git_modified {
                set.extend(ctx.modified_files);
            }
            if args.git_branch {
                set.extend(ctx.branch_changed_files);
            }
        }
        Some(set)
    } else {
        None
    };

    let mut files: Vec<DirEntryMeta> = entries
        .into_iter()
        .filter(|e| {
            if e.is_dir {
                return false;
            }
            let rel = normalize_rel_path(&e.path);
            let file_name = e
                .path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or(rel.as_str());

            if let Some(preset) = args.preset {
                if !matches_preset(&rel, preset) {
                    return false;
                }
            }
            if let Some(ref gset) = git_mod_set {
                if !gset.contains(&rel) {
                    return false;
                }
            }
            if let Some(ref inc) = include_set {
                if !inc.is_match(&rel) && !inc.is_match(file_name) {
                    return false;
                }
            }
            if let Some(ref exc) = exclude_set {
                if exc.is_match(&rel) || exc.is_match(file_name) {
                    return false;
                }
            }
            true
        })
        .collect();

    let mut skeleton_files = HashSet::new();
    if let Some(ref skel_set) = skeleton_glob_set {
        for f in &files {
            let rel = normalize_rel_path(&f.path);
            let file_name = f
                .path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or(rel.as_str());
            if skel_set.is_match(&rel) || skel_set.is_match(file_name) {
                skeleton_files.insert(rel);
            }
        }
    }

    if let Some(budget) = args.max_tokens {
        let local_graph;
        let graph_ref = match dep_graph {
            Some(g) => g,
            None => {
                local_graph = DependencyGraph::build(root, &files);
                &local_graph
            }
        };
        files = prefit_by_estimate_with_graph(
            files,
            &mut skeleton_files,
            args.skeleton,
            budget,
            &args.pinned_rel_paths(),
            Some(graph_ref),
        );
    }

    Ok((files, skeleton_files))
}

/// One-line pre-export redaction report for stderr. Says what was masked, what was skipped, and
/// that pattern matching is not a guarantee. Redaction off is stated explicitly.
fn redaction_report(stats: &ptt::PackStats) -> String {
    let r = &stats.redactions;
    if !r.redaction_enabled {
        return "ptt pack: redaction OFF (--no-redact): credentials in selected files and the diff are included unmasked".to_string();
    }
    let kinds = if r.kinds.is_empty() {
        "no pattern matched".to_string()
    } else {
        r.kinds
            .iter()
            .map(|(kind, count)| format!("{kind}×{count}"))
            .collect::<Vec<_>>()
            .join(", ")
    };
    format!(
        "ptt pack: redaction ON: {} masked ({kinds}); {} files scanned, {} skipped. Pattern-based only: no match does not prove there are no secrets",
        r.total_redactions, r.files_scanned, r.files_skipped
    )
}

pub fn run_pack(args: &PackArgs) -> Result<(), String> {
    let root = args
        .dir
        .canonicalize()
        .map_err(|e| format!("cannot open {}: {e}", args.dir.display()))?;
    if !root.is_dir() {
        return Err(format!("not a directory: {}", root.display()));
    }

    let entries = walk(&root).map_err(|e| e.to_string())?;

    // 1. Inspect git context exactly once.
    let git_context = inspect_git_context(&root);
    let modified_files: HashSet<String> = git_context.modified_files.iter().cloned().collect();

    // 2. Build dependency graph at most once (only when budget is active).
    let dep_graph = if args.max_tokens.is_some() {
        Some(DependencyGraph::build(&root, &entries))
    } else {
        None
    };

    let (filtered_entries, skeleton_files) = filter_entries_for_cli_with_context(
        entries,
        &root,
        args,
        Some(&git_context),
        dep_graph.as_ref(),
    )?;
    let git_diff = if args.git_diff {
        compute_git_diff(&root, 256 * 1024)
    } else {
        None
    };

    let pinned_rel_paths = args.pinned_rel_paths();

    let mut opts = WriteOptions {
        format: args.format,
        include_file_summary: args.include_summary,
        max_file_size: args.max_file_size,
        redact_secrets: args.redact_secrets,
        skeleton_all: args.skeleton,
        skeleton_files,
        git_diff,
        task_prompt: args.task_prompt.clone(),
        tokenizer_model: args.tokenizer_model,
        compute_bpe_tokens: true,
        modified_files,
    };

    // `--max-tokens` is a hard limit on the exact BPE count; reuse the in-memory PreparedWorkspace!
    let (filtered_entries, fitted_workspace) = match args.max_tokens {
        Some(budget) => {
            let (entries, skeleton_files, workspace) = fit_workspace_to_bpe_budget(
                filtered_entries,
                &root,
                &opts,
                budget,
                &pinned_rel_paths,
                dep_graph.as_ref(),
                &|| false,
            )?;
            opts.skeleton_files = skeleton_files;
            (entries, Some(workspace))
        }
        None => (filtered_entries, None),
    };
    let file_count = filtered_entries.iter().filter(|e| !e.is_dir).count();

    if args.copy_to_clipboard {
        let mut buf = Vec::new();
        let stats = if let Some(ref ws) = fitted_workspace {
            ws.render_with_stats(
                &mut buf,
                &filtered_entries,
                &opts.skeleton_files,
                opts.skeleton_all,
            )
            .map_err(|e| e.to_string())?
        } else {
            write_output_with_stats(&mut buf, &filtered_entries, &root, &opts, &|| false)
                .map_err(|e| e.to_string())?
        };
        let text = String::from_utf8(buf).map_err(|e| e.to_string())?;

        if let Some(path) = &args.output {
            write_to_dest_file(path, &root, &filtered_entries, text.as_bytes())?;
        }

        arboard::Clipboard::new()
            .and_then(|mut c| c.set_text(text))
            .map_err(|e| format!("clipboard error: {e}"))?;
        let tok_prefix = if stats.tokenizer_exact { "" } else { "~" };
        eprintln!(
            "ptt pack: copied {} files ({}{} tokens, {}) to clipboard",
            file_count,
            tok_prefix,
            stats.total_tokens,
            opts.tokenizer_model.label()
        );
        eprintln!("{}", redaction_report(&stats));
        return Ok(());
    }

    fn stream<W: Write>(
        writer: W,
        entries: &[DirEntryMeta],
        root: &Path,
        opts: &WriteOptions,
        workspace: Option<&PreparedWorkspace>,
    ) -> Result<ptt::PackStats, String> {
        let mut writer = BufWriter::new(writer);
        let stats = if let Some(ws) = workspace {
            ws.render_with_stats(
                &mut writer,
                entries,
                &opts.skeleton_files,
                opts.skeleton_all,
            )
            .map_err(|error| error.to_string())?
        } else {
            write_output_with_stats(&mut writer, entries, root, opts, &|| false)
                .map_err(|error| error.to_string())?
        };
        writer.flush().map_err(|error| error.to_string())?;
        Ok(stats)
    }

    match &args.output {
        Some(path) => {
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() {
                    fs::create_dir_all(parent).map_err(|e| e.to_string())?;
                }
            }
            if path.exists() {
                let destination = path.canonicalize().map_err(|error| error.to_string())?;
                if filtered_entries
                    .iter()
                    .any(|entry| !entry.is_dir && root.join(&entry.path) == destination)
                {
                    return Err(
                        "Output is also an input file; place it outside the project or ignore it"
                            .into(),
                    );
                }
            }
            let file = fs::File::create(path).map_err(|error| error.to_string())?;
            let stats = stream(
                file,
                &filtered_entries,
                &root,
                &opts,
                fitted_workspace.as_ref(),
            )?;
            let tok_prefix = if stats.tokenizer_exact { "" } else { "~" };
            eprintln!(
                "ptt pack: wrote {} files ({}{} tokens, {}) → {}",
                file_count,
                tok_prefix,
                stats.total_tokens,
                opts.tokenizer_model.label(),
                path.display()
            );
            eprintln!("{}", redaction_report(&stats));
        }
        None => {
            let stats = stream(
                io::stdout().lock(),
                &filtered_entries,
                &root,
                &opts,
                fitted_workspace.as_ref(),
            )?;
            let tok_prefix = if stats.tokenizer_exact { "" } else { "~" };
            eprintln!(
                "ptt pack: {} files · {}{} tokens ({}) · {}",
                file_count,
                tok_prefix,
                stats.total_tokens,
                opts.tokenizer_model.label(),
                format_label(args.format)
            );
            eprintln!("{}", redaction_report(&stats));
        }
    }

    Ok(())
}

fn write_to_dest_file(
    path: &Path,
    root: &Path,
    entries: &[DirEntryMeta],
    bytes: &[u8],
) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent).map_err(|e| e.to_string())?;
        }
    }
    if path.exists() {
        let destination = path.canonicalize().map_err(|error| error.to_string())?;
        if entries
            .iter()
            .any(|entry| !entry.is_dir && root.join(&entry.path) == destination)
        {
            return Err(
                "Output is also an input file; place it outside the project or ignore it".into(),
            );
        }
    }
    fs::write(path, bytes).map_err(|e| e.to_string())
}

fn format_label(f: OutputFormat) -> &'static str {
    match f {
        OutputFormat::Xml => "xml",
        OutputFormat::Markdown => "markdown",
        OutputFormat::Json => "json",
        OutputFormat::Plain => "plain",
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use ptt::core::budget::{fit_to_bpe_budget, fit_to_bpe_budget_with_graph, pack_stats};
    use std::io::Write;
    use tempfile::tempdir;

    #[test]
    fn pack_fixture_writes_xml() {
        let dir = tempdir().unwrap();
        let src = dir.path().join("hello.rs");
        let mut f = fs::File::create(&src).unwrap();
        writeln!(f, "fn main() {{}}").unwrap();

        let out = dir.path().join("out.xml");
        let args = PackArgs {
            dir: dir.path().to_path_buf(),
            output: Some(out.clone()),
            ..Default::default()
        };
        run_pack(&args).unwrap();
        let text = fs::read_to_string(&out).unwrap();
        assert!(
            text.contains("hello.rs") || text.contains("project"),
            "{text}"
        );
        assert!(
            text.contains("fn main") || text.contains("CDATA") || text.contains("file"),
            "{text}"
        );
    }

    #[test]
    fn cli_flags_parse_and_filter_correctly() {
        let argv: Vec<String> = vec![
            "./my-app",
            "--preset",
            "source",
            "--include",
            "*.rs",
            "--exclude",
            "*_test.rs",
            "--skeleton",
            "--no-redact",
            "--max-tokens",
            "64000",
        ]
        .into_iter()
        .map(String::from)
        .collect();
        let parsed = parse_args(&argv).unwrap();
        assert_eq!(parsed.preset, Some(CliPreset::Source));
        assert_eq!(parsed.include_globs, vec!["*.rs"]);
        assert_eq!(parsed.exclude_globs, vec!["*_test.rs"]);
        assert!(parsed.skeleton);
        assert!(!parsed.redact_secrets);
        assert_eq!(parsed.max_tokens, Some(64000));

        // Also verify `--skeleton <GLOB>` selective skeletonization
        let argv_glob: Vec<String> = vec!["--skeleton", "*_test.rs", "./my-app"]
            .into_iter()
            .map(String::from)
            .collect();
        let parsed_glob = parse_args(&argv_glob).unwrap();
        assert!(!parsed_glob.skeleton);
        assert_eq!(parsed_glob.skeleton_globs, vec!["*_test.rs"]);
        assert_eq!(parsed_glob.dir, PathBuf::from("./my-app"));
    }

    #[test]
    fn desktop_arguments_validate_folder_and_reject_typos() {
        let directory = tempdir().unwrap();
        let path = directory.path().to_string_lossy().into_owned();
        assert!(desktop_folder(&[path]).unwrap().is_some());
        assert_eq!(desktop_folder(&[]).unwrap(), None);
        assert!(desktop_folder(&["pak".into(), ".".into()]).is_err());
        assert!(desktop_folder(&["--unknown".into()]).is_err());
    }

    #[test]
    fn max_tokens_is_enforced_on_the_exact_bpe_count() {
        let dir = tempdir().unwrap();
        for i in 0..8 {
            let body: String = (0..120)
                .map(|j| format!("pub fn item_{i}_{j}(value: u64) -> u64 {{ value + {j} }}\n"))
                .collect();
            fs::write(dir.path().join(format!("module_{i}.rs")), body).unwrap();
        }
        let root = dir.path().canonicalize().unwrap();
        let budget: usize = 4_000;
        let args = PackArgs {
            dir: root.clone(),
            max_tokens: Some(budget),
            ..Default::default()
        };
        let entries = walk(&root).unwrap();
        let (filtered, skeleton_files) =
            filter_entries_for_cli_with_context(entries, &root, &args, None, None).unwrap();
        let opts = WriteOptions {
            skeleton_files,
            compute_bpe_tokens: true,
            ..Default::default()
        };
        let (fitted, fit_skeletons) = fit_to_bpe_budget(filtered, &root, &opts, budget).unwrap();

        let opts = WriteOptions {
            skeleton_files: fit_skeletons.clone(),
            ..opts
        };
        let stats = pack_stats(&fitted, &root, &opts).unwrap();
        assert!(
            stats.total_tokens <= budget,
            "pack has {} tokens for budget {budget}",
            stats.total_tokens
        );
        assert!(!fitted.is_empty(), "no file kept");
        assert!(
            fitted.len() < 8 || !fit_skeletons.is_empty(),
            "budget {budget} forced neither a drop nor a skeleton"
        );
    }

    #[test]
    fn parse_format_aliases() {
        assert_eq!(parse_format("md").unwrap(), OutputFormat::Markdown);
        assert_eq!(parse_format("JSON").unwrap(), OutputFormat::Json);
    }

    #[test]
    fn budget_fitting_retains_heavily_imported_file_over_unimported_file() {
        let dir = tempdir().unwrap();
        let src_dir = dir.path().join("src");
        fs::create_dir_all(&src_dir).unwrap();

        // core_hub.rs: central module imported by multiple peers
        let hub_body: String = (0..50)
            .map(|j| format!("pub fn hub_func_{j}() -> u64 {{ {j} }}\n"))
            .collect();
        fs::write(src_dir.join("core_hub.rs"), hub_body).unwrap();

        // user_a.rs and user_b.rs import core_hub
        fs::write(
            src_dir.join("user_a.rs"),
            "use crate::core_hub;\npub fn use_a() { core_hub::hub_func_0(); }\n",
        )
        .unwrap();
        fs::write(
            src_dir.join("user_b.rs"),
            "use crate::core_hub;\npub fn use_b() { core_hub::hub_func_1(); }\n",
        )
        .unwrap();

        // orphan.rs: standalone unimported file
        let orphan_body: String = (0..50)
            .map(|j| format!("pub fn orphan_func_{j}() -> u64 {{ {j} }}\n"))
            .collect();
        fs::write(src_dir.join("orphan.rs"), orphan_body).unwrap();

        let root = dir.path().canonicalize().unwrap();
        let entries = walk(&root).unwrap();

        let dep_graph = DependencyGraph::build(&root, &entries);
        let opts = WriteOptions {
            compute_bpe_tokens: true,
            ..Default::default()
        };

        // Budget that forces dropping one large file: core_hub must be prioritized over orphan.
        let budget = 1300;
        let (fitted, _) = fit_to_bpe_budget_with_graph(
            entries,
            &root,
            &opts,
            budget,
            &HashSet::new(),
            Some(&dep_graph),
        )
        .unwrap();

        let kept_paths: Vec<String> = fitted.iter().map(|e| normalize_rel_path(&e.path)).collect();
        assert!(
            kept_paths.contains(&"src/core_hub.rs".to_string()),
            "heavily imported core_hub.rs should be kept, but kept: {kept_paths:?}"
        );
        assert!(
            !kept_paths.contains(&"src/orphan.rs".to_string()),
            "unimported orphan.rs should be dropped before core_hub.rs, but kept: {kept_paths:?}"
        );
    }
}


//! Token-budget fitting for `--max-tokens` (CLI and MCP pack).
//!
//! Two stages, one owner. [`prefit_by_estimate`] is a cheap pass over file sizes. It upgrades heavy
//! files to skeletons and pre-drops only when far over budget. [`fit_to_bpe_budget_with_pins`] then
//! makes the exact fit against the complete serialized artifact. Pinned paths are never dropped, and a
//! budget too small to hold them fails with an error.

use std::collections::{HashMap, HashSet};
use std::path::Path;

use crate::core::output::{write_output_with_stats, PackStats, PreparedWorkspace, WriteOptions};
use crate::core::tokenizer::estimate_tokens_from_bytes;
use crate::core::walker::{normalize_rel_path, DirEntryMeta};

fn is_low_priority_path(path: &str) -> bool {
    let lower = path.to_ascii_lowercase();
    lower.contains("test")
        || lower.contains("spec")
        || lower.contains("fixture")
        || lower.contains("bench")
        || lower.contains("example")
        || lower.ends_with(".lock")
        || lower.ends_with("-lock.json")
        || lower.ends_with(".md")
        || lower.ends_with(".txt")
}

/// Estimated tokens for a file packed as an AST skeleton: about 30% of its full size.
fn skeleton_cost(tokens: usize) -> usize {
    tokens * 3 / 10
}

/// Indices of `files` in the order budget pressure drops them: non-pinned low-priority paths first,
/// then higher tiers (docs before source), fewer importers, then largest non-pinned files.
pub fn drop_priority_order_with_graph(
    files: &[DirEntryMeta],
    pinned: &HashSet<String>,
    graph: Option<&crate::core::deps::DependencyGraph>,
) -> Vec<usize> {
    let mut order: Vec<usize> = (0..files.len())
        .filter(|&i| !pinned.contains(&normalize_rel_path(&files[i].path)))
        .collect();

    order.sort_by(|&a, &b| {
        let rel_a = normalize_rel_path(&files[a].path);
        let rel_b = normalize_rel_path(&files[b].path);

        let low_a = is_low_priority_path(&rel_a);
        let low_b = is_low_priority_path(&rel_b);

        let importers_a = graph
            .and_then(|g| g.importers.get(&rel_a))
            .map_or(0, |s| s.len());
        let importers_b = graph
            .and_then(|g| g.importers.get(&rel_b))
            .map_or(0, |s| s.len());

        let tier_a = crate::core::output::architectural_tier(&rel_a);
        let tier_b = crate::core::output::architectural_tier(&rel_b);

        // 1. Niski priorytet (testy, locki, docs) odpada jako pierwszy
        low_b
            .cmp(&low_a)
            // 2. Wyższy tier (3 = docs, 0 = src) odpada wcześniej
            .then_with(|| tier_b.cmp(&tier_a))
            // 3. Pliki z mniejszą liczbą importerów odpadają wcześniej
            .then_with(|| importers_a.cmp(&importers_b))
            // 4. Przy remisie najpierw degradujemy największe pliki
            .then_with(|| files[b].size.unwrap_or(0).cmp(&files[a].size.unwrap_or(0)))
    });
    order
}

pub fn drop_priority_order(files: &[DirEntryMeta], pinned: &HashSet<String>) -> Vec<usize> {
    drop_priority_order_with_graph(files, pinned, None)
}

/// Packs `entries` in memory and returns the pack's statistics. Used for exact BPE counts.
pub fn pack_stats(
    entries: &[DirEntryMeta],
    root: &Path,
    opts: &WriteOptions,
) -> Result<PackStats, String> {
    let mut sink = Vec::new();
    write_output_with_stats(&mut sink, entries, root, opts, &|| false).map_err(|e| e.to_string())
}

pub fn fit_to_bpe_budget(
    entries: Vec<DirEntryMeta>,
    root: &Path,
    opts: &WriteOptions,
    budget: usize,
) -> Result<(Vec<DirEntryMeta>, HashSet<String>), String> {
    fit_to_bpe_budget_with_pins(entries, root, opts, budget, &HashSet::new())
}

/// Fits `entries` within `budget` using the complete serialized artifact token count while
/// never dropping files in `pinned_rel_paths`.
pub fn fit_to_bpe_budget_with_pins(
    entries: Vec<DirEntryMeta>,
    root: &Path,
    opts: &WriteOptions,
    budget: usize,
    pinned_rel_paths: &HashSet<String>,
) -> Result<(Vec<DirEntryMeta>, HashSet<String>), String> {
    fit_to_bpe_budget_with_graph(entries, root, opts, budget, pinned_rel_paths, None)
}

/// Fits `entries` within `budget` using single-pass in-memory rendering and graph-centrality drop priority,
/// returning the kept entries and skeleton files.
pub fn fit_to_bpe_budget_with_graph(
    entries: Vec<DirEntryMeta>,
    root: &Path,
    opts: &WriteOptions,
    budget: usize,
    pinned_rel_paths: &HashSet<String>,
    graph: Option<&crate::core::deps::DependencyGraph>,
) -> Result<(Vec<DirEntryMeta>, HashSet<String>), String> {
    let (kept, skeleton_files, _workspace) = fit_workspace_to_bpe_budget(
        entries,
        root,
        opts,
        budget,
        pinned_rel_paths,
        graph,
        &|| false,
    )?;
    Ok((kept, skeleton_files))
}

/// Fits `entries` within `budget` using single-pass in-memory rendering and graph-centrality drop priority,
/// returning the kept entries, skeleton files, and the cached `PreparedWorkspace`.
pub fn fit_workspace_to_bpe_budget(
    entries: Vec<DirEntryMeta>,
    root: &Path,
    opts: &WriteOptions,
    budget: usize,
    pinned_rel_paths: &HashSet<String>,
    graph: Option<&crate::core::deps::DependencyGraph>,
    cancelled: &(dyn Fn() -> bool + Sync),
) -> Result<(Vec<DirEntryMeta>, HashSet<String>, PreparedWorkspace), String> {
    let mut opts = opts.clone();
    opts.compute_bpe_tokens = true;
    let mut kept = entries;
    let workspace = PreparedWorkspace::prepare_for_budget(&kept, root, &opts, &cancelled)
        .map_err(|e| e.to_string())?;

    if kept.is_empty() {
        let stats = workspace
            .render_stats(&kept, &opts.skeleton_files, opts.skeleton_all)
            .map_err(|e| e.to_string())?;
        if stats.total_tokens > budget {
            return Err(format!(
                "Strict token budget ({budget} tokens, {}) exceeded by artifact wrapper/diff/prompt overhead ({} tokens) with 0 files",
                opts.tokenizer_model.label(),
                stats.total_tokens
            ));
        }
        return Ok((kept, opts.skeleton_files, workspace));
    }

    loop {
        if cancelled() {
            return Err("operation cancelled".into());
        }
        let stats = workspace
            .render_stats(&kept, &opts.skeleton_files, opts.skeleton_all)
            .map_err(|e| e.to_string())?;
        if stats.total_tokens <= budget {
            return Ok((kept, opts.skeleton_files, workspace));
        }
        let exact: HashMap<String, usize> = stats
            .file_tokens
            .iter()
            .map(|f| (f.path.clone(), f.tokens))
            .collect();
        let tokens_of = |e: &DirEntryMeta| {
            exact
                .get(&normalize_rel_path(&e.path))
                .copied()
                .unwrap_or(0)
        };
        let order = drop_priority_order_with_graph(&kept, pinned_rel_paths, graph);
        let mut running = stats.total_tokens;

        // Round A: upgrade full non-pinned files to skeletons, lowest priority first, then pack again.
        if !opts.skeleton_all {
            let mut upgraded = false;
            for &idx in &order {
                if running <= budget {
                    break;
                }
                let rel = normalize_rel_path(&kept[idx].path);
                if let Some(wf) = workspace.file_by_path(&rel) {
                    if let Some(skel_tok) = wf.skeleton_tokens {
                        if wf.full_tokens > skel_tok && !opts.skeleton_files.contains(&rel) {
                            let saved = wf.full_tokens - skel_tok;
                            running = running.saturating_sub(saved);
                            opts.skeleton_files.insert(rel);
                            upgraded = true;
                        }
                    }
                }
            }
            if upgraded {
                continue;
            }
        }

        // If no non-pinned files can be dropped (either only 1 file remains or all remaining files are pinned),
        // fail closed with a clear diagnostic rather than silently dropping a pinned file or overflowing.
        let min_keep = pinned_rel_paths.len().max(1);
        if kept.len() <= min_keep || order.is_empty() {
            let only_rel = kept
                .first()
                .map(|e| normalize_rel_path(&e.path))
                .unwrap_or_else(|| "<none>".to_string());
            return Err(format!(
                "Strict token budget ({budget} tokens, {}) cannot fit minimum/pinned artifact: '{}' (and {} pinned files) require {} total tokens ({} content + {} wrapper/diff/prompt overhead)",
                opts.tokenizer_model.label(),
                only_rel,
                pinned_rel_paths.len(),
                stats.total_tokens,
                stats.content_tokens,
                stats.overhead_tokens
            ));
        }

        // Round B: drop non-pinned files in priority order until the exact estimate fits, then pack again.
        let mut dropped = HashSet::new();
        for &idx in &order {
            if running <= budget || kept.len() - dropped.len() <= min_keep {
                break;
            }
            running = running.saturating_sub(tokens_of(&kept[idx]).max(1));
            dropped.insert(idx);
        }
        if dropped.is_empty() {
            if let Some(&idx) = order.first() {
                dropped.insert(idx);
            }
        }
        kept = kept
            .into_iter()
            .enumerate()
            .filter_map(|(i, e)| (!dropped.contains(&i)).then_some(e))
            .collect();
    }
}

/// Heuristic pre-fit for `--max-tokens`, run before the exact fit. `skeleton_all` is `--skeleton`.
/// Upgrades heavy files to skeletons while the estimate is over budget, then drops low-priority
/// files only when the estimate is more than twice the budget.
pub fn prefit_by_estimate(
    files: Vec<DirEntryMeta>,
    skeleton_files: &mut HashSet<String>,
    skeleton_all: bool,
    budget: usize,
    pinned_rel_paths: &HashSet<String>,
) -> Vec<DirEntryMeta> {
    prefit_by_estimate_with_graph(
        files,
        skeleton_files,
        skeleton_all,
        budget,
        pinned_rel_paths,
        None,
    )
}

/// Heuristic pre-fit for `--max-tokens`, run before the exact fit. `skeleton_all` is `--skeleton`.
/// Upgrades heavy files to skeletons while the estimate is over budget, then drops low-priority
/// files only when the estimate is more than twice the budget.
pub fn prefit_by_estimate_with_graph(
    mut files: Vec<DirEntryMeta>,
    skeleton_files: &mut HashSet<String>,
    skeleton_all: bool,
    budget: usize,
    pinned_rel_paths: &HashSet<String>,
    graph: Option<&crate::core::deps::DependencyGraph>,
) -> Vec<DirEntryMeta> {
    // Files already marked for skeleton mode (`--skeleton` or a glob) cost ~30% of their full size.
    let mut total_est: usize = files
        .iter()
        .map(|f| {
            let tok = estimate_tokens_from_bytes(f.size.unwrap_or(0));
            let rel = normalize_rel_path(&f.path);
            if skeleton_all || skeleton_files.contains(&rel) {
                skeleton_cost(tok)
            } else {
                tok
            }
        })
        .sum();

    // Pass 1 (heuristic): upgrade heavy files to AST skeleton mode while the estimate exceeds the budget.
    if total_est > budget {
        let order = drop_priority_order_with_graph(&files, pinned_rel_paths, graph);
        for &idx in &order {
            if total_est <= budget {
                break;
            }
            let rel = normalize_rel_path(&files[idx].path);
            let tok = estimate_tokens_from_bytes(files[idx].size.unwrap_or(0));
            if tok > 20 && !skeleton_all && !skeleton_files.contains(&rel) {
                skeleton_files.insert(rel);
                let saved = tok - skeleton_cost(tok);
                total_est = total_est.saturating_sub(saved);
            }
        }
    }

    // Pass 2 (heuristic): pre-drop only when the estimate is far above the budget. The exact counts
    // in `fit_to_bpe_budget_with_pins` decide the final fit, so this keeps a 2x margin.
    if total_est > budget * 2 {
        let order = drop_priority_order_with_graph(&files, pinned_rel_paths, graph);
        let mut dropped = HashSet::new();
        for &idx in &order {
            if total_est <= budget * 2 || files.len() - dropped.len() <= 1 {
                break;
            }
            let rel = normalize_rel_path(&files[idx].path);
            let tok = estimate_tokens_from_bytes(files[idx].size.unwrap_or(0));
            let effective = if skeleton_files.contains(&rel) {
                skeleton_cost(tok)
            } else {
                tok
            };
            dropped.insert(idx);
            total_est = total_est.saturating_sub(effective);
        }

        if !dropped.is_empty() {
            files = files
                .into_iter()
                .enumerate()
                .filter_map(|(i, f)| (!dropped.contains(&i)).then_some(f))
                .collect();
        }
    }

    files
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::core::output::{OutputFormat, WriteOptions};
    use crate::core::tokenizer::TokenizerModel;
    use crate::core::walker::walk;
    use std::fs;
    use std::path::PathBuf;
    use tempfile::tempdir;

    #[test]
    fn strict_budget_measures_entire_serialized_artifact_in_every_format() {
        use crate::core::tokenizer::count_tokens_with_model;

        let dir = tempdir().unwrap();
        let nested = dir
            .path()
            .join("deeply/nested/path/with/many/segments/for/overhead");
        fs::create_dir_all(&nested).unwrap();
        fs::write(
            nested.join("escape_heavy.rs"),
            "pub fn check() -> &'static str {\n    \"<tag attr=\\\"val\\\"> & ]]> \\n \\t\"\n}\n",
        )
        .unwrap();
        fs::write(
            dir.path().join("second.rs"),
            (0..60)
                .map(|i| format!("pub fn helper_{i}(x: usize) -> usize {{ x + {i} }}\n"))
                .collect::<String>(),
        )
        .unwrap();

        let root = dir.path().canonicalize().unwrap();
        let entries = walk(&root).unwrap();
        let files: Vec<DirEntryMeta> = entries.into_iter().filter(|e| !e.is_dir).collect();

        for format in [
            OutputFormat::Xml,
            OutputFormat::Markdown,
            OutputFormat::Json,
            OutputFormat::Plain,
        ] {
            let opts = WriteOptions {
                format,
                include_file_summary: true,
                git_diff: Some("diff --git a/second.rs b/second.rs\n+pub fn added() {}\n".into()),
                task_prompt: Some("Verify <xml> & \"json\" escaping under budget.".into()),
                tokenizer_model: TokenizerModel::O200kBase,
                compute_bpe_tokens: true,
                ..Default::default()
            };
            let mut full_buf = Vec::new();
            let full_stats =
                write_output_with_stats(&mut full_buf, &files, &root, &opts, &|| false).unwrap();
            let rendered_str = String::from_utf8(full_buf).unwrap();
            let exact_doc_tokens = count_tokens_with_model(&rendered_str, opts.tokenizer_model);

            // total_tokens must equal the exact BPE count of the complete serialized artifact.
            assert_eq!(
                full_stats.total_tokens, exact_doc_tokens,
                "format {format:?} total_tokens mismatch"
            );
            assert!(
                full_stats.total_tokens > full_stats.content_tokens,
                "format {format:?} must count wrapper/diff/prompt overhead"
            );
            assert_eq!(
                full_stats.overhead_tokens,
                full_stats.total_tokens - full_stats.content_tokens
            );
            assert!(full_stats.tokenizer_exact);

            // Fit to a tight budget that forces skeletonization or dropping second.rs.
            let tight_budget = full_stats.total_tokens - 50;
            let (fitted, skels) =
                fit_to_bpe_budget(files.clone(), &root, &opts, tight_budget).unwrap();
            let fitted_opts = WriteOptions {
                skeleton_files: skels.clone(),
                ..opts.clone()
            };
            let mut fit_buf = Vec::new();
            let fit_stats =
                write_output_with_stats(&mut fit_buf, &fitted, &root, &fitted_opts, &|| false)
                    .unwrap();
            let fit_str = String::from_utf8(fit_buf).unwrap();
            let fit_exact = count_tokens_with_model(&fit_str, fitted_opts.tokenizer_model);
            assert_eq!(fit_stats.total_tokens, fit_exact);
            assert!(
                fit_exact <= tight_budget,
                "format {format:?}: emitted {fit_exact} tokens > budget {tight_budget}"
            );

            // Determinism check: repeated fit produces identical file list, skeletons, and bytes.
            let (fitted2, skels2) =
                fit_to_bpe_budget(files.clone(), &root, &opts, tight_budget).unwrap();
            assert_eq!(fitted, fitted2);
            assert_eq!(skels, skels2);
        }
    }

    #[test]
    fn strict_budget_fails_closed_when_single_file_or_overhead_exceeds_budget() {
        let dir = tempdir().unwrap();
        let body: String = (0..80)
            .map(|i| format!("Line {i}: plain text that cannot be AST-skeletonized.\n"))
            .collect();
        fs::write(dir.path().join("notes.txt"), body).unwrap();
        let root = dir.path().canonicalize().unwrap();
        let entries: Vec<DirEntryMeta> = walk(&root)
            .unwrap()
            .into_iter()
            .filter(|e| !e.is_dir)
            .collect();

        let opts = WriteOptions {
            format: OutputFormat::Xml,
            compute_bpe_tokens: true,
            ..Default::default()
        };
        let err = fit_to_bpe_budget(entries, &root, &opts, 25).unwrap_err();
        assert!(
            err.contains("Strict token budget (25 tokens"),
            "unexpected error: {err}"
        );
    }

    fn plain_body(tag: &str, lines: usize) -> String {
        (0..lines)
            .map(|i| format!("{tag} line {i}: plain text that cannot be AST-skeletonized.\n"))
            .collect()
    }

    fn exact_artifact_tokens(entries: &[DirEntryMeta], root: &Path, opts: &WriteOptions) -> usize {
        let mut sink = Vec::new();
        write_output_with_stats(&mut sink, entries, root, opts, &|| false)
            .unwrap()
            .total_tokens
    }

    #[test]
    fn strict_budget_never_drops_pinned_files_and_stays_within_budget() {
        let dir = tempdir().unwrap();
        fs::write(dir.path().join("pinned.txt"), plain_body("pin", 4)).unwrap();
        fs::write(dir.path().join("other_a.txt"), plain_body("aaa", 80)).unwrap();
        fs::write(dir.path().join("other_b.txt"), plain_body("bbb", 80)).unwrap();
        let root = dir.path().canonicalize().unwrap();
        let entries: Vec<DirEntryMeta> = walk(&root)
            .unwrap()
            .into_iter()
            .filter(|e| !e.is_dir)
            .collect();
        let pinned: HashSet<String> = ["pinned.txt".to_string()].into_iter().collect();
        let opts = WriteOptions {
            format: OutputFormat::Xml,
            compute_bpe_tokens: true,
            ..Default::default()
        };

        let pinned_only: Vec<DirEntryMeta> = entries
            .iter()
            .filter(|e| normalize_rel_path(&e.path) == "pinned.txt")
            .cloned()
            .collect();
        let budget = exact_artifact_tokens(&pinned_only, &root, &opts) + 40;
        let full = exact_artifact_tokens(&entries, &root, &opts);
        assert!(
            full > budget,
            "fixture must force dropping: {full} <= {budget}"
        );

        let (kept, _) =
            fit_to_bpe_budget_with_pins(entries.clone(), &root, &opts, budget, &pinned).unwrap();
        let kept_paths: Vec<String> = kept.iter().map(|e| normalize_rel_path(&e.path)).collect();
        assert!(
            kept_paths.iter().any(|p| p == "pinned.txt"),
            "pinned file was dropped: {kept_paths:?}"
        );
        assert!(kept.len() < entries.len(), "fit should drop unpinned files");
        let final_tokens = exact_artifact_tokens(&kept, &root, &opts);
        assert!(final_tokens <= budget, "{final_tokens} > {budget}");
    }

    #[test]
    fn strict_budget_fails_closed_when_pinned_file_alone_exceeds_budget() {
        let dir = tempdir().unwrap();
        fs::write(dir.path().join("pinned.txt"), plain_body("pin", 80)).unwrap();
        fs::write(dir.path().join("other.txt"), plain_body("other", 4)).unwrap();
        let root = dir.path().canonicalize().unwrap();
        let entries: Vec<DirEntryMeta> = walk(&root)
            .unwrap()
            .into_iter()
            .filter(|e| !e.is_dir)
            .collect();
        let pinned: HashSet<String> = ["pinned.txt".to_string()].into_iter().collect();
        let opts = WriteOptions {
            format: OutputFormat::Xml,
            compute_bpe_tokens: true,
            ..Default::default()
        };
        let err = fit_to_bpe_budget_with_pins(entries, &root, &opts, 60, &pinned).unwrap_err();
        assert!(err.contains("pinned"), "unexpected error: {err}");
    }

    #[test]
    fn strict_budget_fit_is_deterministic_across_repeated_runs() {
        let dir = tempdir().unwrap();
        for (name, tag) in [("a.txt", "aa"), ("b.txt", "bb"), ("c.txt", "cc")] {
            fs::write(dir.path().join(name), plain_body(tag, 60)).unwrap();
        }
        let root = dir.path().canonicalize().unwrap();
        let opts = WriteOptions {
            format: OutputFormat::Markdown,
            compute_bpe_tokens: true,
            ..Default::default()
        };
        let run = || {
            let entries: Vec<DirEntryMeta> = walk(&root)
                .unwrap()
                .into_iter()
                .filter(|e| !e.is_dir)
                .collect();
            let (kept, skeletons) = fit_to_bpe_budget(entries, &root, &opts, 1500).unwrap();
            let mut paths: Vec<String> = kept.iter().map(|e| normalize_rel_path(&e.path)).collect();
            paths.sort();
            let mut skel: Vec<String> = skeletons.into_iter().collect();
            skel.sort();
            (paths, skel)
        };
        let first = run();
        for _ in 0..3 {
            assert_eq!(run(), first);
        }
    }

    #[test]
    fn single_pass_bpe_fitting_prepares_each_file_once() {
        let dir = tempdir().unwrap();
        let root = dir.path().canonicalize().unwrap();
        // Create files that require both Round A (skeleton upgrades) and Round B (file drops)
        fs::write(
            root.join("core.rs"),
            "pub fn calculate(x: i32) -> i32 {\n    let a = x * 2;\n    let b = a + 10;\n    b\n}\n",
        )
        .unwrap();
        fs::write(
            root.join("util.rs"),
            "pub fn helper(y: i32) -> i32 {\n    let z = y + 1;\n    z\n}\n",
        )
        .unwrap();
        fs::write(
            root.join("notes.txt"),
            "This is documentation and release notes that can be dropped.\n",
        )
        .unwrap();

        let entries: Vec<DirEntryMeta> = walk(&root)
            .unwrap()
            .into_iter()
            .filter(|e| !e.is_dir)
            .collect();

        let opts = WriteOptions {
            format: OutputFormat::Xml,
            compute_bpe_tokens: true,
            ..Default::default()
        };

        // Budget that forces skeletonization or dropping of files
        let (kept, skeletons) = fit_to_bpe_budget(entries, &root, &opts, 260).unwrap();
        assert!(!kept.is_empty());
        let kept_paths: Vec<String> = kept.iter().map(|e| normalize_rel_path(&e.path)).collect();
        assert!(kept_paths.len() < 3);
        assert!(!skeletons.is_empty() || kept_paths.len() < 3);
    }

    #[test]
    fn drop_priority_order_with_graph_protects_importers_and_tiers() {
        let entries = vec![
            DirEntryMeta {
                path: PathBuf::from("src/isolated.rs"),
                is_dir: false,
                size: Some(100),
            },
            DirEntryMeta {
                path: PathBuf::from("src/core_hub.rs"),
                is_dir: false,
                size: Some(100),
            },
            DirEntryMeta {
                path: PathBuf::from("tests/smoke_test.rs"),
                is_dir: false,
                size: Some(50),
            },
            DirEntryMeta {
                path: PathBuf::from("docs/architecture.md"),
                is_dir: false,
                size: Some(50),
            },
        ];

        let mut graph = crate::core::deps::DependencyGraph::default();
        let mut core_importers = std::collections::BTreeSet::new();
        core_importers.insert("src/app.rs".to_string());
        core_importers.insert("src/worker.rs".to_string());
        core_importers.insert("src/api.rs".to_string());
        graph
            .importers
            .insert("src/core_hub.rs".to_string(), core_importers);

        let order = drop_priority_order_with_graph(&entries, &HashSet::new(), Some(&graph));
        let ordered_paths: Vec<String> = order
            .iter()
            .map(|&i| normalize_rel_path(&entries[i].path))
            .collect();

        // Low priority / test / doc should drop first:
        // tests/smoke_test.rs and docs/architecture.md are low priority (contain "test", end with .md)
        assert!(
            ordered_paths[0] == "tests/smoke_test.rs" || ordered_paths[0] == "docs/architecture.md"
        );
        assert!(
            ordered_paths[1] == "tests/smoke_test.rs" || ordered_paths[1] == "docs/architecture.md"
        );

        // Between source files, isolated.rs has 0 importers, core_hub.rs has 3 importers.
        // Therefore, isolated.rs must be dropped BEFORE core_hub.rs!
        let isolated_idx = ordered_paths
            .iter()
            .position(|p| p == "src/isolated.rs")
            .unwrap();
        let hub_idx = ordered_paths
            .iter()
            .position(|p| p == "src/core_hub.rs")
            .unwrap();
        assert!(
            isolated_idx < hub_idx,
            "core_hub.rs (high centrality) should drop AFTER isolated.rs: {ordered_paths:?}"
        );
    }
}


//! High-quality output generation (XML is the primary recommended format for LLMs).
//!
//! Follows repomix / Anthropic best practices for XML-tagged context, including:
//! - Parallel file reading, UTF-8/UTF-16 decoding, secret redaction, AST skeletonizing,
//!   and exact BPE tokenization via `rayon`
//! - Directory-level canonical root cache so `resolve_under_canonical_root` only checks
//!   unique parent directories once
//! - Optional `<git_diff>` block and Anthropic-optimal `<task_instructions>` placement
//!   at the end of the prompt.

use std::collections::{HashMap, HashSet};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

use rayon::prelude::*;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use crate::core::preview::{is_link, open_verified_regular_file, resolve_under_canonical_root};
use crate::core::secrets::{redact_secrets_with_report, RedactionSummary};
use crate::core::skeleton::{extract_skeleton, language_for_path};
use crate::core::text::{decode_text, markdown_fence, TextError};
use crate::core::tokenizer::{count_tokens_with_model, TokenizerModel};
use crate::core::walker::{normalize_rel_path, DirEntryMeta};

/// Default per-file size limit when the caller does not specify one.
pub const DEFAULT_MAX_FILE_SIZE: u64 = 2 * 1024 * 1024; // 2 MiB

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum OutputFormat {
    #[default]
    Xml,
    Markdown,
    Json,
    Plain,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum FilePackMode {
    #[default]
    Full,
    Skeleton,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FileTokenStat {
    pub path: String,
    pub bytes: usize,
    pub tokens: usize,
    pub mode: FilePackMode,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PackStats {
    pub files_packed: usize,
    /// Exact (or model-profiled) token count of the complete serialized output artifact,
    /// including all XML/Markdown/JSON/Plain wrappers, directory tree, paths, diff, and prompt.
    pub total_tokens: usize,
    /// Sum of tokens across prepared file contents only (excluding wrapper overhead, diff, and prompt).
    pub content_tokens: usize,
    /// Tokens attributable to formatting wrappers, directory listing, git diff, and task prompt.
    pub overhead_tokens: usize,
    /// Whether `total_tokens` comes from an exact BPE vocabulary (`o200k_base` / `cl100k_base`)
    /// rather than an approximate multiplier profile (`claude` / `gemini`) or byte heuristic.
    pub tokenizer_exact: bool,
    pub file_tokens: Vec<FileTokenStat>,
    pub redactions: RedactionSummary,
}

/// Options for packing files into LLM-ready text.
#[derive(Clone, Debug)]
pub struct WriteOptions {
    pub format: OutputFormat,
    pub include_file_summary: bool,
    pub max_file_size: u64,
    pub redact_secrets: bool,
    pub skeleton_all: bool,
    pub skeleton_files: HashSet<String>,
    pub git_diff: Option<String>,
    pub task_prompt: Option<String>,
    pub tokenizer_model: TokenizerModel,
    pub compute_bpe_tokens: bool,
    pub modified_files: HashSet<String>,
}

impl Default for WriteOptions {
    fn default() -> Self {
        Self {
            format: OutputFormat::Xml,
            include_file_summary: true,
            max_file_size: DEFAULT_MAX_FILE_SIZE,
            redact_secrets: true,
            skeleton_all: false,
            skeleton_files: HashSet::new(),
            git_diff: None,
            task_prompt: None,
            tokenizer_model: TokenizerModel::O200kBase,
            compute_bpe_tokens: false,
            modified_files: HashSet::new(),
        }
    }
}

#[derive(Clone, Debug)]
pub struct PreparedWorkspaceFile {
    pub meta: DirEntryMeta,
    pub path: String,
    pub ext: String,
    pub size: Option<u64>,
    pub full_content: String,
    pub full_tokens: usize,
    pub skeleton_content: Option<String>,
    pub skeleton_tokens: Option<usize>,
    pub redactions: RedactionSummary,
    pub is_text_ok: bool,
    pub is_modified: bool,
}

#[derive(Clone, Debug)]
struct CachedRender {
    kept_paths: Vec<PathBuf>,
    skeleton_files: HashSet<String>,
    skeleton_all: bool,
    rendered: Vec<u8>,
    stats: PackStats,
}

#[derive(Clone, Debug)]
pub struct PreparedWorkspace {
    files: Vec<PreparedWorkspaceFile>,
    files_by_path: HashMap<String, usize>,
    root: PathBuf,
    options: WriteOptions,
    last_render: Arc<Mutex<Option<CachedRender>>>,
}

impl PreparedWorkspace {
    /// Reads, decodes, and redacts each file in `entries` exactly once. Precomputes full content,
    /// tokens, and skeleton content (for supported languages).
    pub fn prepare<F>(
        entries: &[DirEntryMeta],
        root: &Path,
        options: &WriteOptions,
        cancelled: &F,
    ) -> std::io::Result<Self>
    where
        F: Fn() -> bool + Sync,
    {
        Self::prepare_with_mode(entries, root, options, cancelled, false)
    }

    /// Precomputes skeletons for all supported files, used by the token budget fitting loop.
    pub fn prepare_for_budget<F>(
        entries: &[DirEntryMeta],
        root: &Path,
        options: &WriteOptions,
        cancelled: &F,
    ) -> std::io::Result<Self>
    where
        F: Fn() -> bool + Sync,
    {
        Self::prepare_with_mode(entries, root, options, cancelled, true)
    }

    /// Reads, decodes, and redacts each file once, optionally precomputing AST skeletons for all files.
    pub fn prepare_with_mode<F>(
        entries: &[DirEntryMeta],
        root: &Path,
        options: &WriteOptions,
        cancelled: &F,
        precompute_all_skeletons: bool,
    ) -> std::io::Result<Self>
    where
        F: Fn() -> bool + Sync,
    {
        let canonical_root = std::fs::canonicalize(root)?;
        let root = canonical_root.as_path();
        let file_metas: Vec<&DirEntryMeta> = entries.iter().filter(|e| !e.is_dir).collect();
        let valid_parents = build_valid_parent_cache(root, &file_metas);

        let prepare_one = |f: &DirEntryMeta| -> PreparedWorkspaceFile {
            let path_str = display_path(&f.path);
            let ext = f
                .path
                .extension()
                .and_then(|e| e.to_str())
                .unwrap_or("")
                .to_string();
            let is_modified = options.modified_files.contains(&path_str);

            let (full_content, redactions, is_text_ok) = read_and_redact_file(
                root,
                &f.path,
                &valid_parents,
                options.max_file_size,
                options.redact_secrets,
            );

            let (skeleton_content, skeleton_tokens) = if is_text_ok {
                let should_compute = precompute_all_skeletons
                    || options.skeleton_all
                    || options.skeleton_files.contains(&path_str);
                if should_compute {
                    let lang = language_for_path(&f.path);
                    if lang != "other" {
                        let skel = extract_skeleton(&full_content, lang);
                        let tok = if options.compute_bpe_tokens {
                            count_tokens_with_model(&skel, options.tokenizer_model)
                        } else {
                            ((skel.len() as f64) / 3.8).round() as usize
                        };
                        (Some(skel), Some(tok))
                    } else {
                        (None, None)
                    }
                } else {
                    (None, None)
                }
            } else {
                (None, None)
            };

            let full_tokens = if options.compute_bpe_tokens {
                count_tokens_with_model(&full_content, options.tokenizer_model)
            } else {
                ((full_content.len() as f64) / 3.8).round() as usize
            };

            PreparedWorkspaceFile {
                meta: (*f).clone(),
                path: path_str,
                ext,
                size: f.size,
                full_content,
                full_tokens,
                skeleton_content,
                skeleton_tokens,
                redactions,
                is_text_ok,
                is_modified,
            }
        };

        let prepared_files: Vec<PreparedWorkspaceFile> = if file_metas.len() < 16 {
            let mut out = Vec::with_capacity(file_metas.len());
            for f in file_metas {
                ensure_not_cancelled(cancelled)?;
                out.push(prepare_one(f));
            }
            out
        } else {
            file_metas
                .par_iter()
                .map(|f| {
                    if cancelled() {
                        return Err(std::io::Error::new(
                            std::io::ErrorKind::Interrupted,
                            "output superseded by a newer request",
                        ));
                    }
                    Ok(prepare_one(f))
                })
                .collect::<std::io::Result<Vec<_>>>()?
        };

        let mut files_by_path = HashMap::with_capacity(prepared_files.len());
        for (i, pf) in prepared_files.iter().enumerate() {
            files_by_path.insert(pf.path.clone(), i);
        }

        Ok(Self {
            files: prepared_files,
            files_by_path,
            root: canonical_root,
            options: options.clone(),
            last_render: Arc::new(Mutex::new(None)),
        })
    }

    pub fn files(&self) -> &[PreparedWorkspaceFile] {
        &self.files
    }

    pub fn file_by_path(&self, rel_path: &str) -> Option<&PreparedWorkspaceFile> {
        let norm = normalize_rel_path(Path::new(rel_path));
        self.files_by_path
            .get(&norm)
            .or_else(|| self.files_by_path.get(rel_path))
            .and_then(|&idx| self.files.get(idx))
    }

    pub fn render_with_stats<W: Write>(
        &self,
        writer: &mut W,
        kept_entries: &[DirEntryMeta],
        skeleton_files: &HashSet<String>,
        skeleton_all: bool,
    ) -> std::io::Result<PackStats> {
        let (rendered, stats) =
            self.render_in_memory(kept_entries, skeleton_files, skeleton_all)?;
        writer.write_all(&rendered)?;
        Ok(stats)
    }

    pub fn render_stats(
        &self,
        kept_entries: &[DirEntryMeta],
        skeleton_files: &HashSet<String>,
        skeleton_all: bool,
    ) -> std::io::Result<PackStats> {
        let (_rendered, stats) =
            self.render_in_memory(kept_entries, skeleton_files, skeleton_all)?;
        Ok(stats)
    }

    pub fn render_in_memory(
        &self,
        kept_entries: &[DirEntryMeta],
        skeleton_files: &HashSet<String>,
        skeleton_all: bool,
    ) -> std::io::Result<(Vec<u8>, PackStats)> {
        let kept_paths: Vec<PathBuf> = kept_entries.iter().map(|e| e.path.clone()).collect();
        if let Ok(guard) = self.last_render.lock() {
            if let Some(ref cached) = *guard {
                if cached.skeleton_all == skeleton_all
                    && cached.skeleton_files == *skeleton_files
                    && cached.kept_paths == kept_paths
                {
                    return Ok((cached.rendered.clone(), cached.stats.clone()));
                }
            }
        }

        let kept_files: Vec<&DirEntryMeta> = kept_entries.iter().filter(|e| !e.is_dir).collect();
        let ordered = architectural_order(&kept_files, &self.options.modified_files);

        let mut prepared: Vec<PreparedFile> = Vec::with_capacity(ordered.len());
        for meta in &ordered {
            let rel = display_path(&meta.path);
            if let Some(&idx) = self.files_by_path.get(&rel) {
                let wf = &self.files[idx];
                let want_skeleton = skeleton_all || skeleton_files.contains(&wf.path);
                let (mode, content, tokens) = match (
                    want_skeleton && wf.is_text_ok,
                    &wf.skeleton_content,
                    wf.skeleton_tokens,
                ) {
                    (true, Some(skel), Some(tok)) => (FilePackMode::Skeleton, skel.clone(), tok),
                    _ => (FilePackMode::Full, wf.full_content.clone(), wf.full_tokens),
                };

                prepared.push(PreparedFile {
                    path: wf.path.clone(),
                    ext: wf.ext.clone(),
                    size: wf.size,
                    mode,
                    content,
                    tokens,
                    redactions: wf.redactions.clone(),
                    is_modified: wf.is_modified,
                });
            }
        }

        let mut rendered = Vec::new();
        let mut extra_redactions = RedactionSummary {
            redaction_enabled: self.options.redact_secrets,
            ..RedactionSummary::default()
        };
        match self.options.format {
            OutputFormat::Xml => write_xml_prepared(
                &mut rendered,
                &kept_files,
                &prepared,
                &self.root,
                &self.options,
                &mut extra_redactions,
            )?,
            OutputFormat::Markdown => write_markdown_prepared(
                &mut rendered,
                &prepared,
                &self.root,
                &self.options,
                &mut extra_redactions,
            )?,
            OutputFormat::Json => write_json_prepared(
                &mut rendered,
                &prepared,
                &self.root,
                &self.options,
                &mut extra_redactions,
            )?,
            OutputFormat::Plain => write_plain_prepared(
                &mut rendered,
                &prepared,
                &self.root,
                &self.options,
                &mut extra_redactions,
            )?,
        }

        let mut stats = PackStats {
            files_packed: prepared.len(),
            total_tokens: 0,
            content_tokens: 0,
            overhead_tokens: 0,
            tokenizer_exact: self.options.compute_bpe_tokens
                && self.options.tokenizer_model.is_exact_bpe(),
            file_tokens: Vec::with_capacity(prepared.len()),
            redactions: extra_redactions,
        };

        for pf in prepared {
            stats.content_tokens += pf.tokens;
            stats.redactions.merge(&pf.redactions);
            stats.file_tokens.push(FileTokenStat {
                path: pf.path,
                bytes: pf.content.len(),
                tokens: pf.tokens,
                mode: pf.mode,
            });
        }

        if self.options.compute_bpe_tokens {
            let rendered_str = std::str::from_utf8(&rendered)
                .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;
            stats.total_tokens =
                count_tokens_with_model(rendered_str, self.options.tokenizer_model);
        } else {
            let approx_total = ((rendered.len() as f64) / 3.8).round() as usize;
            stats.total_tokens = approx_total.max(stats.content_tokens);
        }
        stats.overhead_tokens = stats.total_tokens.saturating_sub(stats.content_tokens);

        if let Ok(mut guard) = self.last_render.lock() {
            *guard = Some(CachedRender {
                kept_paths,
                skeleton_files: skeleton_files.clone(),
                skeleton_all,
                rendered: rendered.clone(),
                stats: stats.clone(),
            });
        }

        Ok((rendered, stats))
    }
}

struct PreparedFile {
    path: String,
    ext: String,
    size: Option<u64>,
    mode: FilePackMode,
    content: String,
    tokens: usize,
    redactions: RedactionSummary,
    is_modified: bool,
}

/// Main high-quality writer.
pub fn write_output<W: Write>(
    writer: &mut W,
    entries: &[DirEntryMeta],
    root: &Path,
    options: &WriteOptions,
) -> std::io::Result<()> {
    write_output_cancellable(writer, entries, root, options, &|| false)
}

/// Like `write_output`, but checks `cancelled` before reading each file and stops with
/// `ErrorKind::Interrupted` once it returns true (e.g. a newer request superseded this one).
pub fn write_output_cancellable<W: Write>(
    writer: &mut W,
    entries: &[DirEntryMeta],
    root: &Path,
    options: &WriteOptions,
    cancelled: &dyn Fn() -> bool,
) -> std::io::Result<()> {
    let canonical_root = std::fs::canonicalize(root)?;
    let root = canonical_root.as_path();
    let files: Vec<&DirEntryMeta> = entries.iter().filter(|e| !e.is_dir).collect();
    let valid_parents = build_valid_parent_cache(root, &files);
    let ordered = architectural_order(&files, &options.modified_files);

    let mut dummy_redactions = RedactionSummary::default();
    match options.format {
        OutputFormat::Xml => {
            write_xml_header(writer, &files, root, options)?;
            for f in &ordered {
                ensure_not_cancelled(cancelled)?;
                let pf = prepare_single_file(f, root, &valid_parents, options);
                write_xml_file_entry(writer, &pf)?;
            }
            write_xml_footer(writer, options, &mut dummy_redactions)
        }
        OutputFormat::Markdown => {
            write_markdown_header(writer, root, options)?;
            for f in &ordered {
                ensure_not_cancelled(cancelled)?;
                let pf = prepare_single_file(f, root, &valid_parents, options);
                write_markdown_file_entry(writer, &pf)?;
            }
            write_markdown_footer(writer, options, &mut dummy_redactions)
        }
        OutputFormat::Json => {
            let mut prepared = Vec::with_capacity(files.len());
            for f in &ordered {
                ensure_not_cancelled(cancelled)?;
                prepared.push(prepare_single_file(f, root, &valid_parents, options));
            }
            write_json_prepared(writer, &prepared, root, options, &mut dummy_redactions)
        }
        OutputFormat::Plain => {
            write_plain_header(writer, root, options)?;
            for f in &ordered {
                ensure_not_cancelled(cancelled)?;
                let pf = prepare_single_file(f, root, &valid_parents, options);
                write_plain_file_entry(writer, &pf)?;
            }
            write_plain_footer(writer, options, &mut dummy_redactions)
        }
    }
}

/// Parallelized writer that also returns [`PackStats`] (redaction summary + per-file token stats).
pub fn write_output_with_stats<W, F>(
    writer: &mut W,
    entries: &[DirEntryMeta],
    root: &Path,
    options: &WriteOptions,
    cancelled: &F,
) -> std::io::Result<PackStats>
where
    W: Write,
    F: Fn() -> bool + Sync,
{
    let workspace = PreparedWorkspace::prepare(entries, root, options, cancelled)?;
    workspace.render_with_stats(
        writer,
        entries,
        &options.skeleton_files,
        options.skeleton_all,
    )
}

/// Architectural emission tier for `<files>` content (lower is emitted first). Truncating a pack
/// from the bottom then drops docs and CI metadata before source code. `<directory_structure>`
/// stays alphabetical and is unaffected.
///
/// 0 = source and entrypoints, 1 = manifests and build configs, 2 = tests and examples,
/// 3 = documentation, CI metadata and everything else.
pub fn architectural_tier(rel: &str) -> u8 {
    let lower = normalize_rel_path(Path::new(rel)).to_ascii_lowercase();
    let name = lower.rsplit('/').next().unwrap_or(&lower);

    const MANIFESTS: &[&str] = &[
        "cargo.toml",
        "package.json",
        "tauri.conf.json",
        "pyproject.toml",
        "go.mod",
        "makefile",
        "dockerfile",
        "build.rs",
    ];
    if MANIFESTS.contains(&name) || (name.starts_with("tsconfig") && name.ends_with(".json")) {
        return 1;
    }

    fn in_dir(lower: &str, dir: &str) -> bool {
        lower.starts_with(&format!("{dir}/")) || lower.contains(&format!("/{dir}/"))
    }
    let is_test_name = name.contains(".test.")
        || name.contains(".spec.")
        || name.contains("_test.")
        || name.starts_with("test_");
    if is_test_name
        || ["tests", "e2e", "examples", "benches"]
            .iter()
            .any(|d| in_dir(&lower, d))
    {
        return 2;
    }

    const SOURCE_DIRS: &[&str] = &[
        "src", "lib", "app", "pkg", "cmd", "internal", "crates", "packages",
    ];
    const SOURCE_EXTS: &[&str] = &[
        ".rs", ".ts", ".tsx", ".js", ".jsx", ".py", ".go", ".cs", ".java", ".c", ".cpp", ".h",
        ".hpp",
    ];
    let is_source_ext = SOURCE_EXTS.iter().any(|e| lower.ends_with(e));
    if is_source_ext || SOURCE_DIRS.iter().any(|d| in_dir(&lower, d)) {
        return 0;
    }

    3
}

/// `files` ordered for content emission: unmodified files first, modified files last,
/// both sorted by [`architectural_tier`], then by path.
pub fn architectural_order<'a>(
    files: &[&'a DirEntryMeta],
    modified_files: &HashSet<String>,
) -> Vec<&'a DirEntryMeta> {
    let mut ordered: Vec<&DirEntryMeta> = files.to_vec();
    ordered.sort_by_cached_key(|f| {
        let rel = normalize_rel_path(&f.path);
        let is_mod = modified_files.contains(&rel);
        (is_mod, architectural_tier(&rel), rel)
    });
    ordered
}

fn ensure_not_cancelled(cancelled: &dyn Fn() -> bool) -> std::io::Result<()> {
    if cancelled() {
        Err(std::io::Error::new(
            std::io::ErrorKind::Interrupted,
            "output superseded by a newer request",
        ))
    } else {
        Ok(())
    }
}

/// Validates unique parent directories once against `canonical_root`, caching valid canonical
/// parent paths in a `HashMap<PathBuf, PathBuf>`.
fn build_valid_parent_cache(root: &Path, files: &[&DirEntryMeta]) -> HashMap<PathBuf, PathBuf> {
    let mut unique_parents: HashSet<PathBuf> = HashSet::new();
    for f in files {
        let parent = f.path.parent().unwrap_or(Path::new("")).to_path_buf();
        unique_parents.insert(parent);
    }

    let mut valid_parents = HashMap::with_capacity(unique_parents.len());
    for parent in unique_parents {
        if parent.as_os_str().is_empty() || parent == Path::new(".") {
            valid_parents.insert(parent, root.to_path_buf());
        } else if let Ok(canon_dir) = resolve_under_canonical_root(root, &parent.to_string_lossy())
        {
            if canon_dir.is_dir() {
                valid_parents.insert(parent, canon_dir);
            }
        }
    }
    valid_parents
}

/// Resolves a file path using the pre-validated parent directory cache, while still checking
/// the file's own `symlink_metadata` (`!is_link`) and `canonicalize().starts_with(root)`.
fn resolve_file_with_parent_cache(
    root: &Path,
    relative: &Path,
    valid_parents: &HashMap<PathBuf, PathBuf>,
) -> std::io::Result<PathBuf> {
    let rel_str = relative.to_string_lossy();
    if rel_str.is_empty() || rel_str == "." || Path::new(rel_str.as_ref()).is_absolute() {
        return resolve_under_canonical_root(root, &rel_str);
    }
    // Check that the filename itself is a single normal component
    let Some(file_name) = relative.file_name() else {
        return resolve_under_canonical_root(root, &rel_str);
    };
    let parent = relative.parent().unwrap_or(Path::new(""));
    let Some(canon_parent) = valid_parents.get(parent) else {
        // Fallback to full component-by-component check so error kind is preserved
        return resolve_under_canonical_root(root, &rel_str);
    };
    let joined = canon_parent.join(file_name);
    let metadata = std::fs::symlink_metadata(&joined)?;
    if is_link(&metadata) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "symlinks and reparse points are not allowed",
        ));
    }
    let full = std::fs::canonicalize(&joined)?;
    if !full.starts_with(root) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "path is outside the project root",
        ));
    }
    Ok(full)
}

fn prepare_single_file(
    f: &DirEntryMeta,
    root: &Path,
    valid_parents: &HashMap<PathBuf, PathBuf>,
    options: &WriteOptions,
) -> PreparedFile {
    let path_str = display_path(&f.path);
    let ext = f
        .path
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("")
        .to_string();
    let mode = if options.skeleton_all || options.skeleton_files.contains(&path_str) {
        FilePackMode::Skeleton
    } else {
        FilePackMode::Full
    };

    let (raw_content, redactions, is_text_ok) = read_and_redact_file(
        root,
        &f.path,
        valid_parents,
        options.max_file_size,
        options.redact_secrets,
    );

    let content = if is_text_ok && mode == FilePackMode::Skeleton {
        let lang = language_for_path(&f.path);
        extract_skeleton(&raw_content, lang)
    } else {
        raw_content
    };

    let tokens = if options.compute_bpe_tokens {
        count_tokens_with_model(&content, options.tokenizer_model)
    } else {
        ((content.len() as f64) / 3.8).round() as usize
    };

    let is_modified = options.modified_files.contains(&path_str);

    PreparedFile {
        path: path_str,
        ext,
        size: f.size,
        mode,
        content,
        tokens,
        redactions,
        is_modified,
    }
}

fn display_path(path: &Path) -> String {
    normalize_rel_path(path)
}

fn escape_xml_attr(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&apos;"),
            c if c.is_control() && c != '\t' && c != '\n' && c != '\r' => {
                // Strip illegal XML 1.0 control chars from attributes
            }
            c => out.push(c),
        }
    }
    out
}

/// Write text inside a CDATA section, safely splitting on the `]]>` terminator.
fn write_cdata<W: Write>(w: &mut W, content: &str) -> std::io::Result<()> {
    writeln!(w, "      <![CDATA[")?;
    // XML forbids `]]>` inside CDATA; split and re-open sections.
    let mut rest = content;
    while let Some(idx) = rest.find("]]>") {
        write!(w, "{}]]]]><![CDATA[>", &rest[..idx])?;
        rest = &rest[idx + 3..];
    }
    write!(w, "{rest}")?;
    writeln!(w, "\n      ]]>")?;
    Ok(())
}

/// Returns the trimmed task prompt, masked with the same rules as file contents and the Git diff
/// when redaction is on. Masked counts are merged into `extra_redactions` so the report covers them.
fn task_prompt_text(
    options: &WriteOptions,
    extra_redactions: &mut RedactionSummary,
) -> Option<String> {
    let prompt = options
        .task_prompt
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())?;
    if options.redact_secrets {
        let (redacted, summary) = redact_secrets_with_report(prompt);
        extra_redactions.merge(&summary);
        Some(redacted.into_owned())
    } else {
        Some(prompt.to_string())
    }
}

fn write_xml_header<W: Write>(
    w: &mut W,
    files: &[&DirEntryMeta],
    root: &Path,
    options: &WriteOptions,
) -> std::io::Result<()> {
    let root_disp = escape_xml_attr(&root_label(root));
    writeln!(w, "<project_context>")?;
    writeln!(
        w,
        "  <source>This file was generated by ptt (ProjectToText) from {root_disp}</source>"
    )?;
    writeln!(w, "  <instruction>Below is the complete (curated) content of the project. Use it for code analysis, refactoring, or implementation tasks.</instruction>")?;
    writeln!(
        w,
        "  <reading_info>Files were read respecting .gitignore (and .pttignore if present). Large files (&gt;{} bytes) and binaries are replaced with notes. Text files decoded as UTF-8 or BOM-declared UTF-16.</reading_info>",
        options.max_file_size
    )?;

    if options.include_file_summary {
        writeln!(w, "  <file_summary>")?;
        writeln!(w, "    Total files included: {}", files.len())?;
        // Oversized files are replaced by a note, so they are not counted as included bytes.
        if options.modified_files.is_empty() {
            let total_size: u64 = files
                .iter()
                .filter_map(|f| f.size)
                .filter(|&size| size <= options.max_file_size)
                .sum();
            writeln!(w, "    Total size: {total_size} bytes")?;
        } else {
            let base_size: u64 = files
                .iter()
                .filter(|f| {
                    !options
                        .modified_files
                        .contains(&normalize_rel_path(&f.path))
                })
                .filter_map(|f| f.size)
                .filter(|&size| size <= options.max_file_size)
                .sum();
            writeln!(w, "    Unmodified base size: {base_size} bytes")?;
        }
        writeln!(
            w,
            "    Note: File contents were read with size limits ({} bytes max), binary detection, and UTF-8 / BOM-declared UTF-16 decoding.",
            options.max_file_size
        )?;
        writeln!(w, "  </file_summary>")?;
    }

    writeln!(w, "  <directory_structure>")?;
    for f in files {
        writeln!(w, "    {}", display_path(&f.path))?;
    }
    writeln!(w, "  </directory_structure>")?;
    writeln!(w, "  <files>")?;
    Ok(())
}

fn write_xml_file_entry<W: Write>(w: &mut W, pf: &PreparedFile) -> std::io::Result<()> {
    let path_attr = escape_xml_attr(&pf.path);
    let status_attr = if pf.is_modified {
        " status=\"modified\""
    } else {
        ""
    };
    match pf.mode {
        FilePackMode::Full => writeln!(w, "    <file path=\"{path_attr}\"{status_attr}>")?,
        FilePackMode::Skeleton => writeln!(
            w,
            "    <file path=\"{path_attr}\" mode=\"skeleton\"{status_attr}>"
        )?,
    }
    write_cdata(w, &pf.content)?;
    writeln!(w, "    </file>")
}

fn write_xml_footer<W: Write>(
    w: &mut W,
    options: &WriteOptions,
    extra_redactions: &mut RedactionSummary,
) -> std::io::Result<()> {
    writeln!(w, "  </files>")?;

    if let Some(diff) = options
        .git_diff
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        let diff_text = if options.redact_secrets {
            let (redacted, summary) = redact_secrets_with_report(diff);
            extra_redactions.merge(&summary);
            redacted
        } else {
            std::borrow::Cow::Borrowed(diff)
        };
        writeln!(w, "  <git_diff>")?;
        write_cdata(w, &diff_text)?;
        writeln!(w, "  </git_diff>")?;
    }

    if let Some(prompt) = task_prompt_text(options, extra_redactions) {
        // The prompt is free text (e.g. `Vec<T>`, `a && b`), so it is wrapped in CDATA like file
        // contents. Escaping it as plain text would produce invalid XML.
        writeln!(w, "  <task_instructions>")?;
        write_cdata(w, &prompt)?;
        writeln!(w, "  </task_instructions>")?;
    }

    writeln!(w, "</project_context>")
}

fn write_xml_prepared<W: Write>(
    w: &mut W,
    files: &[&DirEntryMeta],
    prepared: &[PreparedFile],
    root: &Path,
    options: &WriteOptions,
    extra_redactions: &mut RedactionSummary,
) -> std::io::Result<()> {
    write_xml_header(w, files, root, options)?;
    for pf in prepared {
        write_xml_file_entry(w, pf)?;
    }
    write_xml_footer(w, options, extra_redactions)
}

fn write_markdown_header<W: Write>(
    w: &mut W,
    root: &Path,
    options: &WriteOptions,
) -> std::io::Result<()> {
    writeln!(w, "# Project Context")?;
    writeln!(w, "Generated from: `{}`", root_label(root))?;
    writeln!(
        w,
        "Reading info: Files processed with size/binary limits (max {} bytes) and encoding handling.\n",
        options.max_file_size
    )
}

fn write_markdown_file_entry<W: Write>(w: &mut W, pf: &PreparedFile) -> std::io::Result<()> {
    let fence = markdown_fence(&pf.content);
    let mod_suffix = if pf.is_modified { " *(modified)*" } else { "" };
    match pf.mode {
        FilePackMode::Full => writeln!(w, "## `{}`{mod_suffix}", pf.path)?,
        FilePackMode::Skeleton => writeln!(w, "## `{}` *(skeleton)*{mod_suffix}", pf.path)?,
    }
    writeln!(w, "{fence}{}", pf.ext)?;
    writeln!(w, "{}", pf.content)?;
    writeln!(w, "{fence}")?;
    writeln!(w)
}

fn write_markdown_footer<W: Write>(
    w: &mut W,
    options: &WriteOptions,
    extra_redactions: &mut RedactionSummary,
) -> std::io::Result<()> {
    if let Some(diff) = options
        .git_diff
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        let diff_text = if options.redact_secrets {
            let (redacted, summary) = redact_secrets_with_report(diff);
            extra_redactions.merge(&summary);
            redacted
        } else {
            std::borrow::Cow::Borrowed(diff)
        };
        let fence = markdown_fence(&diff_text);
        writeln!(w, "## Git Diff (`<git_diff>`)")?;
        writeln!(w, "{fence}diff")?;
        writeln!(w, "{diff_text}")?;
        writeln!(w, "{fence}\n")?;
    }

    if let Some(prompt) = task_prompt_text(options, extra_redactions) {
        writeln!(w, "<task_instructions>")?;
        writeln!(w, "{prompt}")?;
        writeln!(w, "</task_instructions>")?;
    }

    Ok(())
}

fn write_markdown_prepared<W: Write>(
    w: &mut W,
    prepared: &[PreparedFile],
    root: &Path,
    options: &WriteOptions,
    extra_redactions: &mut RedactionSummary,
) -> std::io::Result<()> {
    write_markdown_header(w, root, options)?;
    for pf in prepared {
        write_markdown_file_entry(w, pf)?;
    }
    write_markdown_footer(w, options, extra_redactions)
}

fn write_json_prepared<W: Write>(
    w: &mut W,
    prepared: &[PreparedFile],
    root: &Path,
    options: &WriteOptions,
    extra_redactions: &mut RedactionSummary,
) -> std::io::Result<()> {
    let mut file_objs: Vec<Value> = Vec::with_capacity(prepared.len());
    for pf in prepared {
        let mut obj = json!({
            "path": pf.path,
            "size": pf.size,
            "content": pf.content,
        });
        if pf.mode == FilePackMode::Skeleton {
            obj["mode"] = json!("skeleton");
        }
        if pf.is_modified {
            obj["status"] = json!("modified");
        }
        file_objs.push(obj);
    }

    let mut doc = json!({
        "generator": "ptt (ProjectToText)",
        "root": root_label(root),
        "reading_info": format!(
            "Files read with {} byte limit, binary detection, UTF-8 / BOM-declared UTF-16 decoding.",
            options.max_file_size
        ),
        "file_count": prepared.len(),
        "files": file_objs,
    });

    if let Some(diff) = options
        .git_diff
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        let diff_text = if options.redact_secrets {
            let (redacted, summary) = redact_secrets_with_report(diff);
            extra_redactions.merge(&summary);
            redacted.into_owned()
        } else {
            diff.to_string()
        };
        doc["git_diff"] = json!(diff_text);
    }

    if let Some(prompt) = task_prompt_text(options, extra_redactions) {
        doc["task_instructions"] = json!(prompt);
    }

    let pretty = serde_json::to_string_pretty(&doc)
        .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;
    writeln!(w, "{pretty}")?;
    Ok(())
}

fn write_plain_header<W: Write>(
    w: &mut W,
    root: &Path,
    options: &WriteOptions,
) -> std::io::Result<()> {
    writeln!(w, "Project: {}", root_label(root))?;
    writeln!(
        w,
        "Reading info: Data read with limits ({} bytes), binary skip, UTF-8 / BOM-declared UTF-16.",
        options.max_file_size
    )?;
    writeln!(w, "================================\n")
}

fn write_plain_file_entry<W: Write>(w: &mut W, pf: &PreparedFile) -> std::io::Result<()> {
    let mod_suffix = if pf.is_modified { " [modified]" } else { "" };
    match pf.mode {
        FilePackMode::Full => writeln!(w, ">>> {}{mod_suffix}", pf.path)?,
        FilePackMode::Skeleton => writeln!(w, ">>> {} [skeleton]{mod_suffix}", pf.path)?,
    }
    writeln!(w, "{}", pf.content)?;
    writeln!(w, "--------------------------------\n")
}

fn write_plain_footer<W: Write>(
    w: &mut W,
    options: &WriteOptions,
    extra_redactions: &mut RedactionSummary,
) -> std::io::Result<()> {
    if let Some(diff) = options
        .git_diff
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        let diff_text = if options.redact_secrets {
            let (redacted, summary) = redact_secrets_with_report(diff);
            extra_redactions.merge(&summary);
            redacted
        } else {
            std::borrow::Cow::Borrowed(diff)
        };
        writeln!(w, "<git_diff>")?;
        writeln!(w, "{diff_text}")?;
        writeln!(w, "</git_diff>\n")?;
    }

    if let Some(prompt) = task_prompt_text(options, extra_redactions) {
        writeln!(w, "<task_instructions>")?;
        writeln!(w, "{prompt}")?;
        writeln!(w, "</task_instructions>")?;
    }

    Ok(())
}

fn write_plain_prepared<W: Write>(
    w: &mut W,
    prepared: &[PreparedFile],
    root: &Path,
    options: &WriteOptions,
    extra_redactions: &mut RedactionSummary,
) -> std::io::Result<()> {
    write_plain_header(w, root, options)?;
    for pf in prepared {
        write_plain_file_entry(w, pf)?;
    }
    write_plain_footer(w, options, extra_redactions)
}

/// Project folder name only, so packed output never exposes the absolute path.
fn root_label(root: &Path) -> String {
    root.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| "project".to_string())
}

/// `root` must already be canonical (`write_output` canonicalizes it once).
/// Returns `(content, redaction_summary, is_decoded_text)`.
fn read_and_redact_file(
    root: &Path,
    relative: &Path,
    valid_parents: &HashMap<PathBuf, PathBuf>,
    max_file_size: u64,
    redact: bool,
) -> (String, RedactionSummary, bool) {
    let skipped_summary = || RedactionSummary {
        redaction_enabled: redact,
        files_skipped: 1,
        ..RedactionSummary::default()
    };
    let path = match resolve_file_with_parent_cache(root, relative, valid_parents) {
        Ok(path) => path,
        Err(_) => {
            return (
                "[File skipped: inaccessible or unsafe project path]".into(),
                skipped_summary(),
                false,
            )
        }
    };
    let (file, meta) = match open_verified_regular_file(&path) {
        Ok(pair) => pair,
        Err(e) if e.kind() == std::io::ErrorKind::PermissionDenied => {
            return (
                "[File skipped: not a regular file]".into(),
                skipped_summary(),
                false,
            )
        }
        Err(e) => {
            return (
                format!("[Error reading metadata: {e}]"),
                skipped_summary(),
                false,
            )
        }
    };

    let file_size = meta.len();
    if file_size > max_file_size {
        return (
            format!("[File too large: {file_size} bytes (limit {max_file_size}), skipped]"),
            skipped_summary(),
            false,
        );
    }

    // Enforce the limit while reading from the verified handle, in case a file grows after fstat.
    use std::io::Read;
    let bytes = {
        let mut bytes = Vec::with_capacity(file_size as usize);
        file.take(max_file_size.saturating_add(1))
            .read_to_end(&mut bytes)
            .map(|_| bytes)
    };
    match bytes {
        Ok(bytes) if bytes.len() as u64 > max_file_size => (
            format!("[File too large: limit {max_file_size} bytes, skipped]"),
            skipped_summary(),
            false,
        ),
        Ok(bytes) => match decode_text(&bytes, false) {
            Ok(text) => {
                if redact {
                    let (redacted, mut summary) = redact_secrets_with_report(&text);
                    summary.redaction_enabled = true;
                    summary.files_scanned = 1;
                    (redacted.into_owned(), summary, true)
                } else {
                    (
                        text,
                        RedactionSummary {
                            redaction_enabled: false,
                            files_scanned: 0,
                            files_skipped: 0,
                            ..RedactionSummary::default()
                        },
                        true,
                    )
                }
            }
            Err(TextError::Binary) => (
                format!("[Binary file - {file_size} bytes, content omitted for LLM safety]"),
                skipped_summary(),
                false,
            ),
            Err(TextError::Encoding) => (
                "[Invalid text encoding: use UTF-8 or UTF-16 with BOM]".into(),
                skipped_summary(),
                false,
            ),
        },
        Err(_) => (
            "[Error reading project file]".into(),
            skipped_summary(),
            false,
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::path::PathBuf;

    fn tmp_project() -> (tempfile::TempDir, PathBuf) {
        let dir = tempfile::tempdir().expect("tempdir");
        let root = dir.path().to_path_buf();
        fs::write(root.join("hello.rs"), "fn main() {}\n").unwrap();
        fs::write(root.join("notes.md"), "hello ]]> world\n").unwrap();
        (dir, root)
    }

    fn entries_for(root: &Path) -> Vec<DirEntryMeta> {
        vec![
            DirEntryMeta {
                path: PathBuf::from("hello.rs"),
                is_dir: false,
                size: Some(12),
            },
            DirEntryMeta {
                path: PathBuf::from("notes.md"),
                is_dir: false,
                size: Some(14),
            },
        ]
        .into_iter()
        .map(|mut e| {
            if let Ok(m) = fs::metadata(root.join(&e.path)) {
                e.size = Some(m.len());
            }
            e
        })
        .collect()
    }

    #[test]
    fn json_is_valid_and_roundtrips() {
        let (_dir, root) = tmp_project();
        let entries = entries_for(&root);
        let mut buf = Vec::new();
        let opts = WriteOptions {
            format: OutputFormat::Json,
            include_file_summary: true,
            max_file_size: DEFAULT_MAX_FILE_SIZE,
            ..Default::default()
        };
        write_output(&mut buf, &entries, &root, &opts).unwrap();
        let v: Value = serde_json::from_slice(&buf).expect("valid JSON");
        assert_eq!(v["file_count"], 2);
        assert!(v["files"].as_array().unwrap().len() == 2);
        let content = v["files"][0]["content"].as_str().unwrap();
        assert!(content.contains("fn main") || content.contains("hello"));
    }

    #[test]
    fn task_prompt_secrets_are_masked_in_every_format_and_counted() {
        let (_dir, root) = tmp_project();
        let entries = entries_for(&root);
        let token = concat!("sk-", "abcdefghijklmnopqrstuvwx");
        let prompt = format!("Why does this key fail: {token} ?");
        for format in [
            OutputFormat::Xml,
            OutputFormat::Markdown,
            OutputFormat::Json,
            OutputFormat::Plain,
        ] {
            let opts = WriteOptions {
                format,
                task_prompt: Some(prompt.clone()),
                redact_secrets: true,
                ..Default::default()
            };
            let mut buf = Vec::new();
            let stats =
                write_output_with_stats(&mut buf, &entries, &root, &opts, &|| false).unwrap();
            let text = String::from_utf8(buf).unwrap();
            assert!(!text.contains(token), "{format:?} leaked the prompt secret");
            assert!(
                text.contains("[REDACTED"),
                "{format:?} did not mask the prompt"
            );
            assert!(
                stats.redactions.total_redactions >= 1,
                "{format:?} masked prompt not counted in the report"
            );
        }

        let opts = WriteOptions {
            format: OutputFormat::Plain,
            task_prompt: Some(prompt.clone()),
            redact_secrets: false,
            ..Default::default()
        };
        let mut buf = Vec::new();
        let stats = write_output_with_stats(&mut buf, &entries, &root, &opts, &|| false).unwrap();
        let text = String::from_utf8(buf).unwrap();
        assert!(
            text.contains(token),
            "redaction off must keep the prompt verbatim"
        );
        assert!(!stats.redactions.redaction_enabled);
    }

    #[test]
    fn xml_escapes_cdata_terminator() {
        let (_dir, root) = tmp_project();
        let entries = entries_for(&root);
        let mut buf = Vec::new();
        let opts = WriteOptions {
            format: OutputFormat::Xml,
            include_file_summary: true,
            max_file_size: DEFAULT_MAX_FILE_SIZE,
            ..Default::default()
        };
        write_output(&mut buf, &entries, &root, &opts).unwrap();
        let s = String::from_utf8(buf).unwrap();
        // Raw `]]>` must not appear unescaped inside a single CDATA block
        assert!(s.contains("]]]]><![CDATA[>"));
        assert!(s.contains("<project_context>"));
        assert!(s.contains("path=\"notes.md\""));
    }

    #[test]
    fn xml_escapes_attribute_special_chars() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        let entries = vec![DirEntryMeta {
            path: PathBuf::from("a&b<c>.rs"),
            is_dir: false,
            size: Some(1),
        }];
        let mut buf = Vec::new();
        let opts = WriteOptions {
            format: OutputFormat::Xml,
            ..Default::default()
        };
        write_output(&mut buf, &entries, root, &opts).unwrap();
        let s = String::from_utf8(buf).unwrap();
        assert!(
            s.contains("path=\"a&amp;b&lt;c&gt;.rs\""),
            "expected escaped path attr, got:\n{s}"
        );
        assert_eq!(escape_xml_attr(r#"x"y'z"#), "x&quot;y&apos;z");
    }

    #[test]
    fn respects_max_file_size() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        fs::write(root.join("big.txt"), "abcdefghij").unwrap(); // 10 bytes
        let entries = vec![DirEntryMeta {
            path: PathBuf::from("big.txt"),
            is_dir: false,
            size: Some(10),
        }];
        let mut buf = Vec::new();
        let opts = WriteOptions {
            format: OutputFormat::Plain,
            include_file_summary: false,
            max_file_size: 5,
            ..Default::default()
        };
        write_output(&mut buf, &entries, root, &opts).unwrap();
        let s = String::from_utf8(buf).unwrap();
        assert!(s.contains("File too large"));
        assert!(!s.contains("abcdefghij"));
    }

    #[test]
    fn markdown_handles_nested_fences() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        fs::write(root.join("doc.md"), "```\ncode\n```\n").unwrap();
        let entries = vec![DirEntryMeta {
            path: PathBuf::from("doc.md"),
            is_dir: false,
            size: Some(12),
        }];
        let mut buf = Vec::new();
        let opts = WriteOptions {
            format: OutputFormat::Markdown,
            ..Default::default()
        };
        write_output(&mut buf, &entries, root, &opts).unwrap();
        let s = String::from_utf8(buf).unwrap();
        assert!(s.contains("````md"));
    }

    #[cfg(unix)]
    #[test]
    fn packed_output_skips_symlinks_and_hides_absolute_root() {
        let outside = tempfile::tempdir().unwrap();
        let secret = outside.path().join("secret.env");
        fs::write(&secret, "TOP-SECRET-TOKEN").unwrap();

        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        fs::write(root.join("readme.md"), "hello\n").unwrap();
        std::os::unix::fs::symlink(&secret, root.join("link.env")).unwrap();
        let entries = vec![
            DirEntryMeta {
                path: PathBuf::from("readme.md"),
                is_dir: false,
                size: Some(6),
            },
            DirEntryMeta {
                path: PathBuf::from("link.env"),
                is_dir: false,
                size: Some(16),
            },
        ];

        for format in [
            OutputFormat::Xml,
            OutputFormat::Markdown,
            OutputFormat::Json,
            OutputFormat::Plain,
        ] {
            let mut buf = Vec::new();
            let opts = WriteOptions {
                format,
                ..Default::default()
            };
            write_output(&mut buf, &entries, root, &opts).unwrap();
            let s = String::from_utf8(buf).unwrap();
            assert!(
                !s.contains("TOP-SECRET-TOKEN"),
                "symlink target leaked: {format:?}"
            );
            assert!(
                !s.contains(&root.display().to_string()),
                "absolute root leaked: {format:?}"
            );
        }
    }

    #[test]
    fn escape_xml_attr_basics() {
        assert_eq!(escape_xml_attr(r#"a&b"c"#), "a&amp;b&quot;c");
    }

    #[test]
    fn modified_files_emitted_last_for_kv_cache_stability() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().canonicalize().unwrap();
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(root.join("src/a.rs"), "fn a() {}").unwrap();
        std::fs::write(root.join("src/b.rs"), "fn b() {}").unwrap();
        std::fs::write(root.join("src/c.rs"), "fn c() {}").unwrap();

        let entries = crate::core::walker::walk(&root).unwrap();
        let mut modified = std::collections::HashSet::new();
        modified.insert("src/a.rs".to_string());

        let opts = WriteOptions {
            format: OutputFormat::Xml,
            modified_files: modified,
            ..Default::default()
        };

        let mut buf = Vec::new();
        write_output(&mut buf, &entries, &root, &opts).unwrap();
        let out = String::from_utf8(buf).unwrap();

        let pos_a = out
            .find(r#"<file path="src/a.rs" status="modified">"#)
            .unwrap();
        let pos_b = out.find(r#"<file path="src/b.rs">"#).unwrap();
        let pos_c = out.find(r#"<file path="src/c.rs">"#).unwrap();

        assert!(pos_b < pos_c, "unmodified files keep alphabetical order");
        assert!(pos_c < pos_a, "modified file src/a.rs must be emitted last");
    }

    #[test]
    fn kv_cache_prefix_stays_byte_identical_when_modified_file_grows() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().canonicalize().unwrap();
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(
            root.join("src/lib.rs"),
            "pub fn stable_logic() -> &'static str { \"stable\" }\n",
        )
        .unwrap();
        std::fs::write(root.join("src/active.rs"), "fn tiny() {}\n").unwrap();

        let mut modified = std::collections::HashSet::new();
        modified.insert("src/active.rs".to_string());

        let opts = WriteOptions {
            format: OutputFormat::Xml,
            include_file_summary: true,
            modified_files: modified.clone(),
            ..Default::default()
        };

        // Render 1: active.rs is 13 bytes
        let entries1 = crate::core::walker::walk(&root).unwrap();
        let mut buf1 = Vec::new();
        write_output(&mut buf1, &entries1, &root, &opts).unwrap();
        let out1 = String::from_utf8(buf1).unwrap();

        // Now modify active.rs so it grows to ~500 bytes
        let large_content = (0..30)
            .map(|i| format!("pub fn dynamic_{i}() -> usize {{ {i} }}\n"))
            .collect::<String>();
        std::fs::write(root.join("src/active.rs"), &large_content).unwrap();

        // Render 2: active.rs is ~500 bytes
        let entries2 = crate::core::walker::walk(&root).unwrap();
        let mut buf2 = Vec::new();
        write_output(&mut buf2, &entries2, &root, &opts).unwrap();
        let out2 = String::from_utf8(buf2).unwrap();

        let marker = r#"<file path="src/active.rs" status="modified">"#;
        let pos1 = out1.find(marker).expect("marker must exist in out1");
        let pos2 = out2.find(marker).expect("marker must exist in out2");

        assert_eq!(pos1, pos2, "prefix split point must match");
        assert_eq!(
            &out1[..pos1],
            &out2[..pos2],
            "entire XML prefix before modified file must be 100% byte-for-byte identical"
        );
        assert!(out1[..pos1].contains("<file_summary>"));
        assert!(out1[..pos1].contains("Unmodified base size:"));
        assert!(out1[..pos1].contains(r#"<file path="src/lib.rs">"#));
    }

    #[test]
    fn prepared_workspace_reuses_cached_render_buffer() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().canonicalize().unwrap();
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(root.join("src/lib.rs"), "pub fn cached() -> u32 { 1 }\n").unwrap();

        let entries = crate::core::walker::walk(&root).unwrap();
        let opts = WriteOptions {
            format: OutputFormat::Xml,
            compute_bpe_tokens: true,
            ..Default::default()
        };

        let ws = PreparedWorkspace::prepare_for_budget(&entries, &root, &opts, &|| false).unwrap();
        let skeleton_files = HashSet::new();

        // Call render_stats first (e.g. inside budget loop)
        let stats1 = ws.render_stats(&entries, &skeleton_files, false).unwrap();

        // Now render_with_stats directly afterwards
        let mut buf = Vec::new();
        let stats2 = ws
            .render_with_stats(&mut buf, &entries, &skeleton_files, false)
            .unwrap();

        assert_eq!(stats1.total_tokens, stats2.total_tokens);
        assert!(!buf.is_empty());
        let s = String::from_utf8(buf).unwrap();
        assert!(s.contains("pub fn cached"));
    }
}
